/* Generat de tools/build_atelier.js din content/atelier159.json. Nu edita manual. */
window.ATELIER159 = {"skills":[{"track":"tech","id":"sql-null","title":"SQL: NULL, join-uri și agregări","deck":"sql","order":1,"prereq":null,"summary":"Logica cu trei valori, join-uri care multiplică rânduri, agregări corecte."},{"track":"tech","id":"delta-merge","title":"Delta: MERGE, idempotență și istoric","deck":"delta","order":2,"prereq":"sql-null","summary":"Upsert corect, reluări fără duplicate, time travel și VACUUM."},{"track":"tech","id":"spark-perf","title":"Spark: shuffle, skew și fișiere","deck":"spark","order":3,"prereq":"sql-null","summary":"Unde apare shuffle-ul, cum recunoști skew-ul, fișiere mici și broadcast."},{"track":"tech","id":"stream-state","title":"Streaming: watermark, checkpoint, exactly-once","deck":"stream","order":4,"prereq":"delta-merge","summary":"Timp al evenimentului, stare limitată, scrieri idempotente."},{"track":"tech","id":"uc-access","title":"Unity Catalog: permisiuni și guvernanță","deck":"azure","order":5,"prereq":null,"summary":"Ierarhia de privilegii, filtre pe rânduri, măști pe coloane, proprietari."},{"track":"tech","id":"pipeline-ops","title":"Pipeline-uri: retry, idempotență, alertare","deck":"orchestrare","order":6,"prereq":"delta-merge","summary":"Ce reiei automat, ce nu, cum afli că datele lipsesc."},{"track":"mental","id":"mm-contract","title":"Intrări, ieșiri și contracte","order":1,"prereq":null,"summary":"Ce promite un sistem, ce presupune despre intrări și ce faci când promisiunea e încălcată."},{"track":"mental","id":"mm-identity","title":"Identitate, stare și timp","order":2,"prereq":"mm-contract","summary":"Ce face un lucru unic, cum se schimbă starea, momentul producerii vs. sosirii vs. procesării."},{"track":"mental","id":"mm-retry","title":"Idempotență, repetare și erori parțiale","order":3,"prereq":"mm-identity","summary":"Ce se întâmplă când procesul pică la jumătate și reîncerci."},{"track":"mental","id":"mm-model","title":"Granularitate, modelare și responsabilități","order":4,"prereq":"mm-contract","summary":"Cum împarți o problemă mare în părți clare, cu dependențe puține."},{"track":"mental","id":"mm-invariant","title":"Cazuri limită și invarianți","order":5,"prereq":"mm-contract","summary":"Regulile care rămân adevărate indiferent ce intră în sistem."},{"track":"mental","id":"mm-tradeoff","title":"Compromisuri și scalare","order":6,"prereq":"mm-retry","summary":"Consistență vs. disponibilitate, latență vs. debit, simplu vs. flexibil."},{"track":"mental","id":"mm-observe","title":"Observabilitate și diagnosticare","order":7,"prereq":"mm-retry","summary":"Cum afli ce a mers prost și unde, fără să ghicești."},{"track":"mental","id":"mm-evolve","title":"Evoluție și compatibilitate","order":8,"prereq":"mm-model","summary":"Cum schimbi ceva fără să strici ce depinde de el."}],"exercises":[{"id":"sn-1","skill":"sql-null","level":1,"type":"slot","tag":"null-logic","prompt":"Completează interogarea care găsește clienții fără e-mail completat.","payload":{"template":"SELECT id FROM clienti WHERE email {0};","answers":["IS NULL"],"chips":["IS NULL","= NULL","== NULL","<> ''"]},"hint":"Orice comparație cu `=` față de NULL dă UNKNOWN.","explanation":"`IS NULL` e singura formă care testează lipsa valorii. `= NULL` dă UNKNOWN pentru fiecare rând, deci nu întoarce nimic.","impact":"Un filtru `= NULL` într-un raport de calitate arată „0 clienți fără e-mail”, deși sunt mii: problema rămâne nevăzută."},{"id":"sn-2","skill":"sql-null","level":1,"type":"tradeoff","tag":"null-logic","prompt":"Tabelul `angajati` are 10 rânduri; 3 au `bonus` NULL, restul au valori. Ce întoarce `SELECT COUNT(bonus), COUNT(*) FROM angajati`?","payload":{"options":[{"t":"7 și 10","ok":true},{"t":"10 și 10","ok":false,"why":"COUNT(coloană) ignoră NULL-urile."},{"t":"7 și 7","ok":false,"why":"COUNT(*) numără rândurile, inclusiv cele cu NULL."},{"t":"Eroare: COUNT nu acceptă NULL","ok":false,"why":"COUNT funcționează; doar ignoră NULL-urile."}]},"hint":"Una dintre forme numără rânduri, cealaltă valori.","explanation":"`COUNT(*)` numără rândurile; `COUNT(bonus)` numără doar valorile nenule. Similar, `AVG(bonus)` împarte la 7, nu la 10.","impact":"O medie calculată „pe angajat” cu AVG pe o coloană cu NULL e, de fapt, media celor care au valoare. Raportul supraestimează bonusul mediu."},{"id":"sn-3","skill":"sql-null","level":2,"type":"datacheck","tag":"null-logic","prompt":"Vrei comenzile care NU sunt anulate. `stare` poate fi NULL pentru comenzile noi, care trebuie incluse. Ce filtru dă rezultatul corect?","payload":{"columns":["id","stare"],"rows":[[1,"livrat"],[2,"anulat"],[3,null],[4,"in_curs"],[5,"anulat"]],"expected":[1,3,4],"key":"id","options":[{"t":"stare <> 'anulat'","fn":"r => r.stare !== null && r.stare !== 'anulat'","ok":false},{"t":"stare IS DISTINCT FROM 'anulat'","fn":"r => r.stare !== 'anulat'","ok":true},{"t":"stare NOT IN ('anulat', NULL)","fn":"r => false","ok":false},{"t":"stare = 'livrat'","fn":"r => r.stare === 'livrat'","ok":false}]},"hint":"Ce dă `NULL <> 'anulat'` în SQL?","explanation":"`stare <> 'anulat'` dă UNKNOWN pentru NULL și exclude comanda nouă. `IS DISTINCT FROM` tratează NULL ca valoare comparabilă și o păstrează.","impact":"Comenzile noi dispar din raportul de comenzi active: echipa de livrare nu le vede până nu primesc o stare."},{"id":"sn-4","skill":"sql-null","level":2,"type":"flaw","tag":"join-fanout","prompt":"Raportul de venit pe client dă valori prea mari. Ce linie produce problema?","payload":{"lines":["SELECT c.id, SUM(o.suma) AS venit","FROM clienti c","JOIN comenzi o ON o.client_id = c.id","JOIN adrese a ON a.client_id = c.id","GROUP BY c.id;"],"bad":3},"hint":"Câte adrese poate avea un client?","explanation":"Un client cu 3 adrese își dublează sau triplează fiecare comandă după join-ul cu `adrese`, deci suma crește. Join-ul cu o tabelă 1:N care nu e folosită în agregare multiplică rândurile.","impact":"Venitul raportat e umflat exact pentru clienții cu mai multe adrese; diferența nu se vede la un test pe date mici unde fiecare client are o adresă."},{"id":"sn-5","skill":"sql-null","level":3,"type":"tradeoff","tag":"join-fanout","prompt":"Ai nevoie de venitul pe client și de orașul adresei principale. Clienții pot avea mai multe adrese. Ce abordare alegi?","payload":{"options":[{"t":"Agregi comenzile pe client, apoi faci join cu adresa principală.","ok":true},{"t":"Join cu toate adresele și `SUM(DISTINCT o.suma)`.","ok":false,"why":"DISTINCT pe sume elimină și comenzi legitime cu aceeași valoare."},{"t":"Join cu toate adresele, apoi împarți suma la numărul de adrese.","ok":false,"why":"Fragil și greșit când numărul de adrese diferă de factorul real de multiplicare."},{"t":"Renunți la oraș în raport.","ok":false,"why":"Elimini o cerință în loc să rezolvi modelarea."}]},"hint":"Ce granularitate are fiecare parte înainte de join?","explanation":"Aduci fiecare parte la granularitatea țintei (un rând pe client) înainte de join: agregare pe comenzi și filtrare pe adresa principală.","impact":"Regula „agregă înainte de join când părțile au granularități diferite” previne o clasă întreagă de cifre umflate în rapoarte."},{"id":"sn-6","skill":"sql-null","level":3,"type":"order","tag":"join-fanout","prompt":"Ordonează pașii prin care verifici dacă un join a multiplicat rânduri.","payload":{"steps":["Numeri rândurile tabelului de bază","Verifici unicitatea cheii în tabelul din dreapta","Numeri rândurile după join","Compari totalurile unei măsuri înainte și după join"]},"hint":"Începi cu referința, apoi cauza posibilă, apoi efectul.","explanation":"Știi câte rânduri ar trebui să rămână, verifici dacă cheia din dreapta e unică, apoi confirmi prin numărare și printr-un total de control.","impact":"Un total de control (de exemplu suma vânzărilor) comparat înainte și după join prinde multiplicarea chiar și când numărul de rânduri pare plauzibil."},{"id":"dm-1","skill":"delta-merge","level":1,"type":"slot","tag":"merge-dup","prompt":"Completează MERGE-ul care actualizează clienții existenți și îi inserează pe cei noi.","payload":{"template":"MERGE INTO clienti t USING noi s ON t.id = s.id\nWHEN {0} THEN UPDATE SET *\nWHEN {1} THEN INSERT *;","answers":["MATCHED","NOT MATCHED"],"chips":["MATCHED","NOT MATCHED","NOT MATCHED BY SOURCE","EXISTS"]},"hint":"Ce se întâmplă când cheia există în țintă și când nu?","explanation":"`WHEN MATCHED` tratează rândurile care există în țintă, `WHEN NOT MATCHED` pe cele noi. `NOT MATCHED BY SOURCE` e pentru rândurile din țintă care lipsesc din sursă.","impact":"Un MERGE corect face upsert-ul atomic: fie se aplică tot lotul, fie nimic, fără stări intermediare vizibile."},{"id":"dm-2","skill":"delta-merge","level":1,"type":"tradeoff","tag":"merge-dup","prompt":"Un job zilnic încarcă fișierul de comenzi al zilei. Uneori rulează de două ori. Ce scriere evită duplicatele?","payload":{"options":[{"t":"MERGE pe `comanda_id`.","ok":true},{"t":"`INSERT INTO` la fiecare rulare.","ok":false,"why":"A doua rulare inserează din nou aceleași rânduri."},{"t":"`INSERT INTO`, apoi `SELECT DISTINCT` în rapoarte.","ok":false,"why":"Muți problema la fiecare consumator."},{"t":"`OPTIMIZE` după fiecare încărcare.","ok":false,"why":"Compactarea nu elimină duplicatele."}]},"hint":"Ce operație dă același rezultat dacă o rulezi de două ori?","explanation":"MERGE pe cheia naturală e idempotent: a doua rulare găsește rândurile și le actualizează cu aceleași valori.","impact":"Reîncercările automate devin sigure doar dacă scrierea e idempotentă; altfel fiecare retry e un risc de dublare a cifrelor."},{"id":"dm-3","skill":"delta-merge","level":2,"type":"datacheck","tag":"merge-dup","prompt":"Sursa unui MERGE are mai multe versiuni pentru același `id`. Ce filtru păstrează doar ultima versiune per id, ca MERGE-ul să nu eșueze?","payload":{"columns":["id","versiune","updated_at"],"rows":[[1,"a","2026-11-01"],[1,"b","2026-11-03"],[2,"c","2026-11-02"],[3,"d","2026-11-01"],[3,"e","2026-11-01"]],"expected":[1,2,3],"key":"versiune","expectedKeys":["b","c","e"],"options":[{"t":"row_number() OVER (PARTITION BY id ORDER BY updated_at DESC, versiune DESC) = 1","fn":"(r, all) => !all.some(o => o.id === r.id && (o.updated_at > r.updated_at || (o.updated_at === r.updated_at && o.versiune > r.versiune)))","ok":true},{"t":"row_number() OVER (PARTITION BY id ORDER BY updated_at DESC) = 1","fn":"(r, all) => all.filter(o => o.id === r.id && o.updated_at === r.updated_at).length > 1 ? !all.some(o => o.id === r.id && (o.updated_at > r.updated_at || (o.updated_at === r.updated_at && o.versiune < r.versiune))) : !all.some(o => o.id === r.id && o.updated_at > r.updated_at)","ok":false},{"t":"MAX(updated_at) per id, apoi join înapoi pe (id, updated_at)","fn":"(r, all) => !all.some(o => o.id === r.id && o.updated_at > r.updated_at)","ok":false},{"t":"DISTINCT id","fn":"(r, all) => all.find(o => o.id === r.id) === r","ok":false}]},"hint":"Ce se întâmplă când două versiuni au același `updated_at`?","explanation":"Ordinea trebuie să fie completă: fără coloana de departajare, două rânduri cu același `updated_at` dau un rezultat arbitrar sau două rânduri pentru același id, iar MERGE-ul eșuează.","impact":"Un MERGE care merge în teste poate cădea în producție exact în ziua în care două actualizări au același timestamp."},{"id":"dm-4","skill":"delta-merge","level":2,"type":"flaw","tag":"vacuum-retention","prompt":"După un incident, echipa nu mai poate face time travel la versiunea de ieri. Ce linie a cauzat problema?","payload":{"lines":["OPTIMIZE vanzari;","SET spark.databricks.delta.retentionDurationCheck.enabled = false;","VACUUM vanzari RETAIN 0 HOURS;","DESCRIBE HISTORY vanzari;"],"bad":2},"hint":"Ce comandă șterge fișierele necesare versiunilor vechi?","explanation":"VACUUM cu retenție 0 șterge toate fișierele nereferite de versiunea curentă; versiunile anterioare rămân în istoric, dar nu mai pot fi citite. Linia 2 doar dezactivează protecția.","impact":"Fără time travel, o suprascriere greșită nu mai poate fi anulată cu RESTORE; recuperarea cere reîncărcare din surse."},{"id":"dm-5","skill":"delta-merge","level":3,"type":"tradeoff","tag":"vacuum-retention","prompt":"Stocarea crește, iar echipa vrea să ruleze VACUUM. Auditul cere posibilitatea de a reveni la orice versiune din ultimele 30 de zile. Ce configurezi?","payload":{"options":[{"t":"Retenție de cel puțin 30 de zile.","ok":true},{"t":"VACUUM cu retenția implicită de 7 zile.","ok":false,"why":"Nu acoperă cerința de 30 de zile."},{"t":"Fără VACUUM niciodată.","ok":false,"why":"Respecți auditul, dar stocarea crește nelimitat."},{"t":"VACUUM zilnic cu retenție 0.","ok":false,"why":"Elimină complet time travel."}]},"hint":"Ce leagă cerința de audit de setările tabelului?","explanation":"Răspunsul complet: Retenție de cel puțin 30 de zile pentru fișierele șterse și jurnal. Retenția fișierelor șterse (deletedFileRetentionDuration) și a jurnalului (logRetentionDuration) trebuie să acopere fereastra de audit; VACUUM respectă apoi pragul.","impact":"Costul de stocare și posibilitatea de recuperare sunt un trade-off explicit: retenția se alege din cerințe, nu din obișnuință."},{"id":"dm-6","skill":"delta-merge","level":3,"type":"order","tag":"merge-dup","prompt":"Un job a suprascris greșit tabelul `clienti`. Ordonează pașii de recuperare.","payload":{"steps":["Oprești jobul care scrie în tabel","Găsești în DESCRIBE HISTORY versiunea bună","Verifici conținutul cu VERSION AS OF","Rulezi RESTORE la versiunea bună","Repornești jobul după corectare"]},"hint":"Întâi oprești sursa problemei.","explanation":"Dacă jobul rulează în continuare, poate suprascrie din nou după restaurare. Verifici versiunea înainte de RESTORE, ca să nu restaurezi alta greșită.","impact":"O recuperare făcută în ordinea greșită poate produce încă o versiune proastă și pierde timp prețios în timpul incidentului."},{"id":"sp-1","skill":"spark-perf","level":1,"type":"tradeoff","tag":"shuffle","prompt":"Care dintre aceste operații produce shuffle?","payload":{"options":[{"t":"`groupBy('client').sum('suma')`","ok":true},{"t":"`filter(col('tara') == 'RO')`","ok":false,"why":"Filter e o transformare îngustă."},{"t":"`withColumn('an', year('data'))`","ok":false,"why":"Calculează pe fiecare rând, fără mutarea datelor."},{"t":"`select('id', 'suma')`","ok":false,"why":"Selecția de coloane e îngustă."}]},"hint":"Ce operație are nevoie de toate rândurile aceleiași chei împreună?","explanation":"Agregarea pe cheie cere ca rândurile fiecărui client să ajungă în aceeași partiție, deci date mutate între executori.","impact":"Shuffle-ul e de obicei partea scumpă a unui job: rețea, disc, risc de skew. Îl recunoști ca să-l poți reduce."},{"id":"sp-2","skill":"spark-perf","level":1,"type":"slot","tag":"broadcast","prompt":"Completează join-ul ca tabelul mic de țări să fie trimis tuturor executorilor.","payload":{"template":"vanzari.join({0}(tari), 'cod_tara')","answers":["broadcast"],"chips":["broadcast","repartition","coalesce","cache"]},"hint":"Tabelul mic ajunge întreg la fiecare executor.","explanation":"`broadcast(tari)` evită shuffle-ul tabelului mare: fiecare executor are copia completă a tabelului mic.","impact":"Un hint de broadcast potrivit poate transforma un join de zeci de minute într-unul de câteva minute; pe un tabel mare, poate duce la OOM."},{"id":"sp-3","skill":"spark-perf","level":2,"type":"datacheck","tag":"skew","prompt":"Ai numărul de rânduri pe partiție după un shuffle. Ce regulă semnalează skew-ul (o partiție de cel puțin 5 ori peste mediana celorlalte)?","payload":{"columns":["partitie","randuri"],"rows":[[0,1200],[1,1100],[2,9800],[3,1300],[4,1000],[5,8900],[6,1250],[7,4000]],"expected":[2,5],"key":"partitie","options":[{"t":"randuri >= 5 × mediana","fn":"(r, all) => { const v = all.map(x => x.randuri).sort((a,b)=>a-b); const m = v[Math.floor(v.length/2)]; return r.randuri >= 5*m; }","ok":true},{"t":"randuri > media","fn":"(r, all) => r.randuri > all.reduce((s,x)=>s+x.randuri,0)/all.length","ok":false},{"t":"randuri > 1000","fn":"r => r.randuri > 1000","ok":false},{"t":"randuri = maximul","fn":"(r, all) => r.randuri === Math.max(...all.map(x=>x.randuri))","ok":false}]},"hint":"Media e trasă în sus chiar de partiția mare; mediana nu.","explanation":"Comparația cu mediana izolează partiția anormală. Media e influențată de valoarea extremă, iar „maximul” semnalează mereu o partiție, chiar fără skew.","impact":"O regulă de alertare greșită pentru skew fie țipă la fiecare rulare, fie ratează exact cazul care încetinește jobul."},{"id":"sp-4","skill":"spark-perf","level":2,"type":"flaw","tag":"small-files","prompt":"Jobul de mai jos produce zeci de mii de fișiere mici pe zi. Ce linie e cauza?","payload":{"lines":["df = spark.read.table('raw.evenimente')","df = df.repartition(2000)","df = df.withColumn('zi', to_date('ts'))","df.write.partitionBy('zi', 'client_id').mode('append').saveAsTable('silver.evenimente')"],"bad":3},"hint":"Câte combinații de partiții produce scrierea?","explanation":"Partiționarea pe `client_id` (cardinalitate mare) creează un director pentru fiecare client și zi; fiecare task scrie câte un fișier în fiecare director atins.","impact":"Milioane de fișiere mici încetinesc listarea, citirea și întreținerea; problema crește în fiecare zi."},{"id":"sp-5","skill":"spark-perf","level":3,"type":"tradeoff","tag":"skew","prompt":"Un join pe `client_id` are o cheie (clientul „anonim”) cu 40% din rânduri. AQE e activ, dar taskul tot durează mult. Ce alegi?","payload":{"options":[{"t":"Salting sau tratare separată a cheii.","ok":true},{"t":"Mărești numărul de partiții de shuffle de 10 ori.","ok":false,"why":"Toate rândurile cheii dominante ajung tot într-o partiție."},{"t":"Treci join-ul pe broadcast pentru ambele tabele.","ok":false,"why":"Tabelele mari nu pot fi difuzate."},{"t":"Elimini clientul anonim din date.","ok":false,"why":"Schimbi rezultatul afacerii."}]},"hint":"Unde ajung toate rândurile unei singure chei?","explanation":"Răspunsul complet: Tratezi separat cheia dominantă sau aplici salting pe ea. O singură cheie nu se poate împărți prin mai multe partiții fără intervenție: salting sau procesarea separată a cheii dominante.","impact":"Skew-ul pe o cheie dominantă e frecvent în date reale (client anonim, valoare implicită); recunoașterea lui economisește ore de tuning inutil."},{"id":"sp-6","skill":"spark-perf","level":3,"type":"order","tag":"shuffle","prompt":"Un job a devenit de 3 ori mai lent. Ordonează pașii de diagnostic.","payload":{"steps":["Găsești în Spark UI stage-ul cel mai lung","Compari durata mediană cu maximul taskurilor","Verifici volumul de shuffle și spill","Verifici planul fizic pentru join-uri și filtre"]},"hint":"De la localizare la cauză.","explanation":"Localizezi stage-ul, apoi decizi tipul problemei (skew vs volum), confirmi prin shuffle și spill, iar planul îți arată de ce.","impact":"Un diagnostic ordonat evită schimbările aleatorii de configurare, care adesea mută problema în altă parte."},{"id":"ss-1","skill":"stream-state","level":1,"type":"tradeoff","tag":"watermark","prompt":"Ce face un watermark de 10 minute pe coloana `event_time`?","payload":{"options":[{"t":"Tolerează 10 minute întârziere, apoi curăță starea.","ok":true},{"t":"Procesează un micro-batch la fiecare 10 minute.","ok":false,"why":"Asta e un trigger, nu un watermark."},{"t":"Șterge din sursă evenimentele mai vechi de 10 minute, la fiecare rulare.","ok":false,"why":"Watermark-ul nu modifică sursa."},{"t":"Întârzie toate rezultatele cu exact 10 minute.","ok":false,"why":"Influențează când o fereastră e finală, nu adaugă o întârziere fixă."}]},"hint":"E despre timpul evenimentului, nu despre timpul de procesare.","explanation":"Răspunsul complet: Acceptă întârzieri de până la 10 minute, apoi curăță starea veche. Watermark-ul spune cât de târziu pot sosi evenimentele; datele mai vechi decât pragul pot fi ignorate, iar starea lor eliberată.","impact":"Fără watermark, agregările și deduplicările pe stream păstrează stare la nesfârșit, până la căderea jobului."},{"id":"ss-2","skill":"stream-state","level":1,"type":"slot","tag":"checkpoint","prompt":"Completează scrierea stream-ului astfel încât să poată relua după o cădere de unde a rămas.","payload":{"template":"(df.writeStream\n  .option('{0}', '/Volumes/prod/stare/comenzi_silver')\n  .toTable('silver.comenzi'))","answers":["checkpointLocation"],"chips":["checkpointLocation","path","startingOffsets","maxFilesPerTrigger"]},"hint":"Unde păstrează stream-ul progresul și starea?","explanation":"Checkpoint-ul păstrează offset-urile procesate și starea; la repornire, stream-ul continuă din același punct.","impact":"Fără checkpoint propriu și stabil, o repornire reprocesează sau pierde date."},{"id":"ss-3","skill":"stream-state","level":2,"type":"datacheck","tag":"watermark","prompt":"Watermark-ul curent este 10:00 (maximul event_time văzut 10:10, minus 10 minute). Care evenimente din lotul nou pot fi ignorate ca întârziate?","payload":{"columns":["id","event_time"],"rows":[[1,"09:58"],[2,"10:01"],[3,"10:12"],[4,"09:40"],[5,"10:00"]],"expected":[1,4],"key":"id","options":[{"t":"event_time < watermark (10:00)","fn":"r => r.event_time < '10:00'","ok":true},{"t":"event_time < maximul văzut (10:10)","fn":"r => r.event_time < '10:10'","ok":false},{"t":"event_time <= watermark (10:00)","fn":"r => r.event_time <= '10:00'","ok":false},{"t":"Niciunul; Spark nu ignoră date","fn":"r => false","ok":false}]},"hint":"Pragul este watermark-ul, iar egalitatea nu e „mai vechi”.","explanation":"Evenimentele cu event_time strict mai mic decât watermark-ul pot fi eliminate; cel de 10:00 fix e încă acceptat.","impact":"Înțelegerea exactă a pragului explică de ce unele evenimente „lipsesc” din agregări și cât watermark e nevoie pentru sursele lente."},{"id":"ss-4","skill":"stream-state","level":2,"type":"flaw","tag":"checkpoint","prompt":"Două stream-uri au început să sară și să dubleze date după un deploy. Ce linie e problema?","payload":{"lines":["q1 = comenzi.writeStream.option('checkpointLocation', '/chk/comun').toTable('silver.comenzi')","q2 = plati.writeStream.option('checkpointLocation', '/chk/comun').toTable('silver.plati')","spark.streams.awaitAnyTermination()"],"bad":1},"hint":"Ce trebuie să fie unic pentru fiecare stream?","explanation":"Al doilea stream folosește același checkpoint ca primul; offset-urile și starea se amestecă. Fiecare stream are nevoie de locație proprie.","impact":"Coruperea checkpoint-ului e greu de observat: cifrele par aproape corecte, dar lipsesc sau se dublează loturi întregi."},{"id":"ss-5","skill":"stream-state","level":3,"type":"tradeoff","tag":"exactly-once","prompt":"În `foreachBatch` scrii și într-un tabel Delta, și într-un API extern. Vrei efect „exact o dată” la reprocesare. Ce alegi?","payload":{"options":[{"t":"Scrieri idempotente: Delta cu `txnVersion` și API cu cheie de idempotență din `batchId`.","ok":true},{"t":"Dezactivezi checkpoint-ul ca să nu se reproceseze.","ok":false,"why":"Fără checkpoint pierzi poziția și reprocesezi mai mult."},{"t":"Te bazezi pe garanția exactly-once a lui Spark pentru API.","ok":false,"why":"Garanția nu se extinde la sisteme externe fără idempotență."},{"t":"Scrii mai întâi în API, apoi în Delta.","ok":false,"why":"Ordinea nu previne dublarea la reprocesare."}]},"hint":"Ce identifică unic un micro-batch?","explanation":"Micro-batch-ul poate rula de două ori; fiecare destinație trebuie să recunoască a doua aplicare (batchId, chei de idempotență).","impact":"Plăți, e-mailuri sau notificări trimise de două ori sunt incidente vizibile clienților; idempotența e singura apărare."},{"id":"ss-6","skill":"stream-state","level":3,"type":"order","tag":"checkpoint","prompt":"Trebuie să schimbi schema de ieșire a unui stream în producție. Ordonează pașii siguri.","payload":{"steps":["Verifici dacă schimbarea e compatibilă cu checkpoint-ul existent","Oprești stream-ul curat","Aplici schimbarea și, dacă e incompatibilă, alegi un checkpoint nou și punctul de start","Repornești și verifici primele loturi"]},"hint":"Unele schimbări de interogare nu sunt permise cu același checkpoint.","explanation":"Unele modificări (de exemplu în agregări cu stare) nu sunt compatibile cu starea salvată; decizi înainte cum pornești.","impact":"O repornire neplanificată pe un checkpoint incompatibil cade la pornire sau, mai rău, pornește din punctul greșit."},{"id":"uc-1","skill":"uc-access","level":1,"type":"slot","tag":"uc-hierarchy","prompt":"Completează permisiunile minime ca grupul `analisti` să citească `prod.vanzari.comenzi`.","payload":{"template":"GRANT {0} ON CATALOG prod TO analisti;\nGRANT {1} ON SCHEMA prod.vanzari TO analisti;\nGRANT {2} ON TABLE prod.vanzari.comenzi TO analisti;","answers":["USE CATALOG","USE SCHEMA","SELECT"],"chips":["USE CATALOG","USE SCHEMA","SELECT","MODIFY","ALL PRIVILEGES"]},"hint":"Citirea cere acces la fiecare nivel al ierarhiei.","explanation":"Fără USE CATALOG și USE SCHEMA, SELECT pe tabel nu ajunge; MODIFY sau ALL PRIVILEGES ar da mai mult decât e necesar.","impact":"Permisiunile minime reduc riscul ca un analist să modifice din greșeală date de producție."},{"id":"uc-2","skill":"uc-access","level":1,"type":"tradeoff","tag":"uc-ownership","prompt":"Cine ar trebui să fie proprietarul tabelelor de producție?","payload":{"options":[{"t":"Un grup sau un service principal.","ok":true},{"t":"Inginerul care a creat tabelul.","ok":false,"why":"Când pleacă, tabelul rămâne fără administrator real."},{"t":"Adminul workspace-ului, personal.","ok":false,"why":"Tot o persoană."},{"t":"Nimeni; e mai sigur.","ok":false,"why":"Orice obiect are un proprietar."}]},"hint":"Ce se întâmplă când o persoană pleacă?","explanation":"Proprietarul are control complet; un grup sau un service principal supraviețuiește schimbărilor de echipă.","impact":"Tabelele deținute de foști angajați blochează modificări de schemă și acordări de permisiuni în momente critice."},{"id":"uc-3","skill":"uc-access","level":2,"type":"datacheck","tag":"uc-row-filter","prompt":"Un row filter trebuie să lase fiecare utilizator să vadă doar regiunea grupului său, iar grupul `admin` totul. Utilizatorul curent e în grupul `moldova`. Ce regulă dă rezultatul așteptat?","payload":{"columns":["id","regiune"],"rows":[[1,"moldova"],[2,"banat"],[3,"moldova"],[4,"oltenia"]],"expected":[1,3],"key":"id","context":{"grupuri":["moldova"]},"options":[{"t":"is_account_group_member('admin') OR is_account_group_member(regiune)","fn":"(r, all, ctx) => ctx.grupuri.includes('admin') || ctx.grupuri.includes(r.regiune)","ok":true},{"t":"is_account_group_member(regiune)","fn":"(r, all, ctx) => ctx.grupuri.includes(r.regiune)","ok":false},{"t":"regiune = 'moldova'","fn":"r => r.regiune === 'moldova'","ok":false},{"t":"is_account_group_member('admin')","fn":"(r, all, ctx) => ctx.grupuri.includes('admin')","ok":false}],"accept":[0]},"hint":"Pentru utilizatorul curent mai multe reguli dau același rezultat; alege-o pe cea care respectă toată cerința.","explanation":"Pentru grupul `moldova`, primele trei reguli dau aceleași rânduri, dar doar prima tratează și adminii și nu e scrisă pentru o singură regiune. Testul pe un singur utilizator nu ajunge: verifici regula și cu alte grupuri.","impact":"Un filtru testat doar cu propriul cont pare corect până când un admin nu mai vede nimic sau o altă regiune vede datele Moldovei."},{"id":"uc-4","skill":"uc-access","level":2,"type":"flaw","tag":"uc-hierarchy","prompt":"După rularea scriptului, grupul `bi` poate șterge tabele din producție. Ce linie dă prea mult?","payload":{"lines":["GRANT USE CATALOG ON CATALOG prod TO bi;","GRANT USE SCHEMA ON SCHEMA prod.vanzari TO bi;","GRANT ALL PRIVILEGES ON SCHEMA prod.vanzari TO bi;","GRANT SELECT ON TABLE prod.vanzari.comenzi TO bi;"],"bad":2},"hint":"Ce include „toate privilegiile” pe o schemă?","explanation":"ALL PRIVILEGES pe schemă include modificarea și gestionarea obiectelor; privilegiile se moștenesc pe toate tabelele.","impact":"Un singur GRANT prea larg pe o schemă se propagă la tabele viitoare; auditul îl descoperă de obicei după un incident."},{"id":"uc-5","skill":"uc-access","level":3,"type":"tradeoff","tag":"uc-row-filter","prompt":"20 de țări, fiecare vede doar rândurile ei; HR vede CNP-ul, ceilalți nu. Ce soluție alegi?","payload":{"options":[{"t":"Row filter și column mask.","ok":true},{"t":"20 de copii ale tabelului, câte una pe țară.","ok":false,"why":"Duplici datele și apar diferențe între copii."},{"t":"20 de vederi, plus o vedere pentru HR.","ok":false,"why":"Funcționează, dar e greu de întreținut și ușor de ocolit."},{"t":"Filtrarea în fiecare raport Power BI.","ok":false,"why":"Accesul direct la tabel ocolește filtrul."}]},"hint":"Unde se aplică regula ca să nu poată fi ocolită?","explanation":"Răspunsul complet: Un row filter pe țară și un column mask pe CNP. Row filters și column masks se aplică la nivelul tabelului, pentru orice interogare și orice unealtă.","impact":"Regulile de acces în fiecare raport se pierd la primul raport nou; regula pe tabel se aplică automat."},{"id":"uc-6","skill":"uc-access","level":3,"type":"order","tag":"uc-ownership","prompt":"Un inginer pleacă din firmă și deține tabele de producție. Ordonează pașii.","payload":{"steps":["Listezi obiectele pe care le deține","Transferi proprietatea către grupul echipei","Verifici că joburile nu rulează cu identitatea lui","Îl scoți din grupuri și îi revoci accesul"]},"hint":"Nu tai accesul înainte să muți responsabilitatea.","explanation":"Dacă îl dezactivezi întâi, obiectele și joburile lui pot rămâne fără administrator sau pot cădea.","impact":"Plecările netratate lasă joburi care cad noaptea și tabele pe care nimeni nu le mai poate administra."},{"id":"po-1","skill":"pipeline-ops","level":1,"type":"tradeoff","tag":"retry","prompt":"Care eroare merită reîncercată automat?","payload":{"options":[{"t":"HTTP 503 de la API-ul sursă.","ok":true},{"t":"HTTP 401: token invalid.","ok":false,"why":"Reîncercarea nu repară credențialele."},{"t":"Coloană lipsă în fișierul sursă.","ok":false,"why":"E o problemă de contract; reîncercarea dă aceeași eroare."},{"t":"Eroare de sintaxă în SQL.","ok":false,"why":"Codul trebuie corectat."}]},"hint":"Care dintre ele poate dispărea singură?","explanation":"Erorile tranzitorii (503, timeout, 429) se reîncearcă cu backoff; erorile de configurare sau de date nu.","impact":"Reîncercările pe erori permanente consumă compute și întârzie alerta reală."},{"id":"po-2","skill":"pipeline-ops","level":1,"type":"slot","tag":"freshness","prompt":"Completează verificarea de prospețime: alertă dacă ultima încărcare e mai veche de 26 de ore.","payload":{"template":"SELECT {0}(_ingested_at) < current_timestamp() - INTERVAL {1} HOURS AS intarziat FROM silver.comenzi;","answers":["MAX","26"],"chips":["MAX","MIN","COUNT","26","24","2"]},"hint":"Te interesează cea mai recentă încărcare.","explanation":"MAX(_ingested_at) e momentul ultimei încărcări; marja de 26 de ore acoperă un job zilnic cu întârzieri mici.","impact":"Un job care nu pornește nu dă eroare; doar o verificare de prospețime observă lipsa datelor."},{"id":"po-3","skill":"pipeline-ops","level":2,"type":"datacheck","tag":"freshness","prompt":"Ai numărul de rânduri încărcate pe zi. Ce regulă semnalează doar zilele anormale (sub 50% din mediana ultimelor zile)?","payload":{"columns":["zi","randuri"],"rows":[["2026-11-14",10200],["2026-11-15",9800],["2026-11-16",0],["2026-11-17",10100],["2026-11-18",4100]],"expected":["2026-11-16","2026-11-18"],"key":"zi","options":[{"t":"randuri < 0.5 × mediana","fn":"(r, all) => { const v = all.map(x => x.randuri).sort((a,b)=>a-b); return r.randuri < 0.5 * v[Math.floor(v.length/2)]; }","ok":true},{"t":"randuri = 0","fn":"r => r.randuri === 0","ok":false},{"t":"randuri < ziua precedentă","fn":"(r, all) => { const i = all.indexOf(r); return i > 0 && r.randuri < all[i-1].randuri; }","ok":false},{"t":"randuri < 10000","fn":"r => r.randuri < 10000","ok":false}]},"hint":"O zi cu jumătate din volum e și ea o problemă.","explanation":"Doar `= 0` ratează încărcările parțiale; comparația cu ziua precedentă semnalează și scăderi normale; un prag fix nu se adaptează la volum. Mediana zilelor recente e o referință robustă.","impact":"Încărcările parțiale sunt mai periculoase decât cele lipsă: raportul arată cifre plauzibile, dar greșite."},{"id":"po-4","skill":"pipeline-ops","level":2,"type":"flaw","tag":"retry","prompt":"La reîncercarea automată, jobul a dublat datele zilei. Ce linie face reîncercarea nesigură?","payload":{"lines":["zi = params['zi']","df = extrage_api(zi)","df.write.mode('append').saveAsTable('silver.comenzi')","marcheaza_zi_procesata(zi)"],"bad":2},"hint":"Ce se întâmplă dacă linia 4 nu ajunge să ruleze?","explanation":"Append-ul nu e idempotent: dacă jobul cade după scriere și e reîncercat, aceeași zi se scrie din nou. Soluție: suprascriere pe partiția zilei (replaceWhere) sau MERGE pe cheie.","impact":"Retry-ul transformă o eroare tranzitorie într-o problemă de date: cifrele dublate ajung în rapoarte înainte să le observe cineva."},{"id":"po-5","skill":"pipeline-ops","level":3,"type":"tradeoff","tag":"retry","prompt":"Un API sursă răspunde cu 429 la vârfuri de trafic. Ce politică de reîncercare alegi?","payload":{"options":[{"t":"Backoff exponențial cu jitter.","ok":true},{"t":"Reîncercare imediată, de 50 de ori, fără pauză între ele.","ok":false,"why":"Amplifică încărcarea și prelungește blocarea."},{"t":"Fără reîncercări; marchezi jobul eșuat.","ok":false,"why":"429 e de obicei tranzitorie."},{"t":"Mai multe fire de execuție paralele.","ok":false,"why":"Generezi și mai multe cereri limitate."}]},"hint":"Ce îi spune serverul prin 429?","explanation":"Răspunsul complet: Backoff exponențial cu jitter, respectând `Retry-After`. 429 cere încetinire; backoff-ul exponențial cu jitter distribuie reîncercările, iar `Retry-After` dă intervalul cerut de server.","impact":"Reîncercările agresive pot transforma o limitare temporară într-o blocare a contului de API."},{"id":"po-6","skill":"pipeline-ops","level":3,"type":"order","tag":"freshness","prompt":"Raportul de dimineață arată cifre prea mici. Ordonează pașii de investigație.","payload":{"steps":["Verifici prospețimea și volumul pe zile în stratul gold","Urmărești în amonte unde scade volumul","Verifici rularea și jurnalele jobului din acel strat","Repari, reprocesezi zilele afectate și anunți consumatorii"]},"hint":"De la simptom, spre sursă, apoi remediere.","explanation":"Confirmi simptomul cu date, localizezi stratul unde apare scăderea, găsești cauza, apoi repari și comunici.","impact":"Comunicarea cu consumatorii e parte din remediere: un raport greșit deja distribuit trebuie corectat explicit."},{"id":"mc-1","skill":"mm-contract","level":1,"type":"tradeoff","kind":"invariant","tag":"p-contract","prompt":"Un ghișeu acceptă cereri doar dacă au completat numele și data nașterii. Ce cerere încalcă acest contract?","payload":{"options":[{"t":"O cerere cu nume, dar fără dată de naștere.","ok":true},{"t":"O cerere cu nume și dată, scrisă de mână.","ok":false,"why":"Forma scrisului nu face parte din contract."},{"t":"O cerere depusă la ultima oră a programului.","ok":false,"why":"Ora depunerii nu e o condiție a contractului."},{"t":"O cerere cu nume foarte lung și dată completă.","ok":false,"why":"Lungimea numelui nu e restricționată în enunț."}]},"hint":"Contractul spune exact ce câmpuri sunt obligatorii.","explanation":"Un contract de intrare spune ce trebuie să conțină o cerere ca să fie acceptată. Orice altceva (scris, oră, lungime) nu face parte din promisiune.","impact":"Când contractul e clar, poți respinge devreme intrările invalide, în loc să descoperi problema trei pași mai târziu."},{"id":"mc-2","skill":"mm-contract","level":1,"type":"tradeoff","kind":"compromise","tag":"p-contract","prompt":"Un sistem primește o cerere care încalcă contractul. Ce reacție e cea mai sănătoasă de obicei?","payload":{"options":[{"t":"O respinge clar, cu motivul, înainte de orice modificare.","ok":true},{"t":"O acceptă și completează câmpurile lipsă cu valori inventate.","ok":false,"why":"Valorile inventate ajung în date ca și cum ar fi reale."},{"t":"O acceptă și speră că pașii următori se descurcă.","ok":false,"why":"Problema se mută în alt loc, unde e mai greu de înțeles."},{"t":"O ignoră fără să anunțe pe nimeni.","ok":false,"why":"Expeditorul nu află că cererea s-a pierdut."}]},"hint":"Unde e cel mai ieftin să oprești o problemă?","explanation":"Respingerea devreme și explicită păstrează datele curate și îi spune expeditorului ce să corecteze.","impact":"Datele inventate pentru a „trece mai departe” sunt printre cele mai greu de curățat ulterior."},{"id":"mc-3","skill":"mm-contract","level":2,"type":"flaw","kind":"assumption","tag":"p-missing","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Fiecare comandă are o adresă de livrare.","Calculăm costul transportului după orașul din adresă.","Comenzile fără oraș sunt imposibile, deci nu le tratăm.","Rezultatul se trimite contabilității."],"bad":2},"hint":"Ce se întâmplă cu cazul pe care „nu îl tratăm”?","explanation":"„Imposibil” fără o verificare explicită e o presupunere. O comandă fără oraș va apărea, iar calculul ei va da ceva necontrolat.","impact":"Cazurile declarate imposibile sunt exact cele care cad noaptea, pentru că nimeni nu a scris ce trebuie să se întâmple atunci."},{"id":"mc-4","skill":"mm-contract","level":2,"type":"tradeoff","kind":"invariant","tag":"p-missing","prompt":"O fișă de inventar promite: „cantitatea e mereu un număr ≥ 0”. Ce intrare încalcă promisiunea, deși pare inofensivă?","payload":{"options":[{"t":"Un câmp de cantitate lăsat gol.","ok":true},{"t":"Cantitatea 0.","ok":false,"why":"0 respectă regula ≥ 0."},{"t":"Cantitatea 12 000.","ok":false,"why":"Un număr mare respectă regula."},{"t":"Un produs nou, cu cantitatea 3.","ok":false,"why":"Respectă regula."}]},"hint":"„Gol” e un număr?","explanation":"Lipsa valorii nu e zero. Dacă sistemul tratează golul ca zero sau îl lasă să treacă, promisiunea „mereu un număr” e deja ruptă.","impact":"Confuzia dintre „lipsă” și „zero” schimbă totaluri și decizii (de exemplu comenzi de reaprovizionare)."},{"id":"mc-5","skill":"mm-contract","level":3,"type":"tradeoff","kind":"compromise","tag":"p-contract","prompt":"Un partener trimite uneori cereri cu un câmp opțional nou, necunoscut. Ce politică alegi pentru intrare?","payload":{"options":[{"t":"Accepți câmpurile necunoscute, dar le ignori explicit și le notezi.","ok":true},{"t":"Respingi orice cerere care conține ceva necunoscut.","ok":false,"why":"Strict, dar orice extindere a partenerului îți oprește fluxul."},{"t":"Accepți și interpretezi câmpul după cum pare.","ok":false,"why":"Ghicești sensul unui câmp pe care nu-l cunoști."},{"t":"Copiezi totul fără nicio verificare.","ok":false,"why":"Renunți și la verificarea câmpurilor obligatorii."}]},"hint":"Ce e obligatoriu trebuie verificat strict; ce e necunoscut nu trebuie ghicit.","explanation":"Strict pe ce e obligatoriu, tolerant cu extensiile necunoscute, dar fără să le interpretezi. Notarea lor îți arată când contractul trebuie actualizat.","impact":"Compromisul dintre rigiditate și toleranță decide dacă o schimbare minoră la partener devine incident la tine."},{"id":"mc-6","skill":"mm-contract","level":4,"type":"diagnose","kind":"diagnose","tag":"p-contract","prompt":"Simptom: de luni, 3% din cereri ajung la contabilitate cu suma 0, deși clienții au plătit.","payload":{"hypotheses":[{"t":"Sursa a schimbat formatul sumei.","ok":true},{"t":"Clienții au început să plătească mai puțin.","ok":false,"why":"Nu explică suma exact 0 la plăți existente."},{"t":"Contabilitatea primește prea multe cereri și pierde o parte din ele.","ok":false,"why":"Volumul nu transformă sume în 0."}],"tests":[{"t":"Compari cererile cu suma 0 cu originalele.","ok":true},{"t":"Repornești tot sistemul și urmărești dacă dispare.","ok":false,"why":"Nu testează ipoteza și poate ascunde dovada."},{"t":"Corectezi manual sumele în contabilitate.","ok":false,"why":"Repari simptomul, nu afli cauza."}]},"explanation":"Răspunsul complet: Sursa a schimbat formatul sumei, iar valorile necitibile devin 0. O dată de început clară (luni) și o valoare suspectă (0) sugerează o schimbare de contract la intrare. Testul compară exact cazurile afectate cu originalul.","impact":"Transformarea tăcută a valorilor invalide în 0 e mai periculoasă decât o eroare vizibilă: rapoartele par normale."},{"id":"mi-1","skill":"mm-identity","level":1,"type":"tradeoff","kind":"invariant","tag":"p-identity","prompt":"Într-un sistem de rezervări, ce identifică unic o rezervare?","payload":{"options":[{"t":"Un cod de rezervare unic.","ok":true},{"t":"Numele clientului, împreună cu prenumele lui.","ok":false,"why":"Doi clienți pot avea același nume."},{"t":"Data și ora rezervării.","ok":false,"why":"Mai multe rezervări pot fi făcute în același moment."},{"t":"Numărul camerei.","ok":false,"why":"Aceeași cameră are multe rezervări în timp."}]},"hint":"Ce nu se poate repeta niciodată?","explanation":"Răspunsul complet: Un cod de rezervare generat o singură dată. Identitatea trebuie să fie stabilă și unică. Atributele descriptive (nume, oră, cameră) se pot repeta.","impact":"Identitatea greșită duce la rezervări contopite sau dublate, greu de despărțit ulterior."},{"id":"mi-2","skill":"mm-identity","level":1,"type":"tradeoff","kind":"compromise","tag":"p-time","prompt":"Un colet e scanat la 10:00, mesajul ajunge la sistem la 10:20 și e procesat la 10:25. Ce moment folosești ca să știi când a plecat coletul?","payload":{"options":[{"t":"10:00, producerea.","ok":true},{"t":"10:20, momentul sosirii mesajului.","ok":false,"why":"Include întârzierea transportului mesajului."},{"t":"10:25, momentul procesării.","ok":false,"why":"Include și coada de procesare."},{"t":"Ora curentă, când citești raportul.","ok":false,"why":"Nu are legătură cu evenimentul."}]},"hint":"Întrebarea e despre colet, nu despre sistem.","explanation":"Răspunsul complet: 10:00, momentul producerii evenimentului. Momentul producerii descrie lumea reală. Momentele de sosire și procesare descriu drumul prin sistem.","impact":"Rapoartele construite pe momentul procesării se schimbă când sistemul e lent, deși realitatea nu s-a schimbat."},{"id":"mi-3","skill":"mm-identity","level":2,"type":"flaw","kind":"assumption","tag":"p-order","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Primim stările unei comenzi: creată, plătită, livrată.","Fiecare stare are momentul în care s-a produs.","Ultima stare primită este starea actuală a comenzii.","Afișăm starea actuală clientului."],"bad":2},"hint":"Mesajele ajung mereu în ordinea în care s-au produs?","explanation":"Mesajele pot sosi în altă ordine. Starea actuală se decide după momentul producerii (sau o secvență), nu după ordinea sosirii.","impact":"Un „plătită” sosit după „livrată” poate da înapoi o comandă finalizată în ochii clientului."},{"id":"mi-4","skill":"mm-identity","level":2,"type":"tradeoff","kind":"invariant","tag":"p-identity","prompt":"Regula: „Fiecare comandă are exact o stare finală.” Ce situație o încalcă?","payload":{"options":[{"t":"Aceeași comandă: „livrată” și „anulată”.","ok":true},{"t":"O comandă trece din „creată” în „plătită”.","ok":false,"why":"E o tranziție normală, nu o stare finală dublă."},{"t":"O comandă rămâne „creată” două zile.","ok":false,"why":"Încă nu are stare finală, dar nici două."},{"t":"Două comenzi diferite sunt „livrate” în aceeași zi.","ok":false,"why":"Sunt identități diferite."}]},"hint":"Atenție la aceeași identitate cu două finaluri.","explanation":"Răspunsul complet: Aceeași comandă apare de două ori, una „livrată” și una „anulată”. Două stări finale contradictorii pentru aceeași identitate înseamnă duplicat sau tranziție nepermisă.","impact":"Invarianții pe stări finale prind devreme duplicatele care altfel apar ca diferențe de bani la închiderea lunii."},{"id":"mi-5","skill":"mm-identity","level":3,"type":"tradeoff","kind":"compromise","tag":"p-time","prompt":"Evenimentele pot întârzia până la o oră. Raportul pe ore trebuie publicat cât mai repede, dar și corect. Ce alegi?","payload":{"options":[{"t":"Publici repede o variantă provizorie, apoi o corectezi când trece fereastra de întârziere.","ok":true},{"t":"Publici o singură dată, imediat, și ignori evenimentele întârziate.","ok":false,"why":"Rapid, dar raportul rămâne incomplet permanent."},{"t":"Aștepți o zi întreagă înainte de orice publicare.","ok":false,"why":"Corect, dar inutil pentru decizii rapide."},{"t":"Atribui evenimentele întârziate orei la care au sosit.","ok":false,"why":"Muți evenimente în ora greșită."}]},"hint":"Poți avea două versiuni ale aceluiași raport.","explanation":"Compromisul viteză–completitudine se rezolvă adesea cu rezultate provizorii marcate clar și o versiune finală după fereastra de întârziere.","impact":"Cine citește raportul trebuie să știe dacă cifrele sunt provizorii; altfel corecturile par erori."},{"id":"mi-6","skill":"mm-identity","level":4,"type":"diagnose","kind":"diagnose","tag":"p-order","prompt":"Simptom: unii clienți văd comanda ca „plătită” deși ea a fost deja livrată.","payload":{"hypotheses":[{"t":"Starea urmează ordinea sosirii.","ok":true},{"t":"Clienții au plătit de două ori.","ok":false,"why":"Nu explică întoarcerea la o stare anterioară."},{"t":"Livrarea a fost anulată, iar sistemul a revenit la starea anterioară.","ok":false,"why":"Ar apărea „anulată”, nu „plătită”."}],"tests":[{"t":"Compari momentele de producere și de sosire ale stărilor pentru comenzile afectate.","ok":true},{"t":"Ștergi stările vechi ale tuturor comenzilor.","ok":false,"why":"Distrugi dovezile și istoricul."},{"t":"Ceri clienților să reîncarce pagina.","ok":false,"why":"Nu verifică nimic."}]},"explanation":"Răspunsul complet: Starea e decisă după ordinea sosirii, iar mesajele vin neordonate. Dacă momentul producerii lui „plătită” e înaintea lui „livrată”, dar a sosit după, ai confirmat ipoteza ordinii.","impact":"Diagnosticul cu dovezi (momente comparate) evită „repararea” prin ștergeri care strică istoricul."},{"id":"mr-1","skill":"mm-retry","level":1,"type":"tradeoff","kind":"invariant","tag":"p-double","prompt":"Ce înseamnă că o operație este idempotentă?","payload":{"options":[{"t":"Repetată, dă același rezultat final.","ok":true},{"t":"Se execută foarte repede.","ok":false,"why":"Viteza nu are legătură cu idempotența."},{"t":"Nu poate eșua niciodată.","ok":false,"why":"Poate eșua; important e ce se întâmplă la repetare."},{"t":"Se execută o singură dată pe zi, la ora stabilită.","ok":false,"why":"Frecvența nu definește idempotența."}]},"hint":"Gândește-te la butonul de lift apăsat de trei ori.","explanation":"Răspunsul complet: Dacă o repeți, rezultatul final e același ca după prima execuție. Apăsarea repetată a butonului de lift nu cheamă trei lifturi: efectul rămâne același. Asta e idempotența.","impact":"Orice sistem care reîncearcă automat are nevoie de operații idempotente; altfel fiecare reîncercare poate dubla efectul."},{"id":"mr-2","skill":"mm-retry","level":1,"type":"tradeoff","kind":"retry","tag":"p-double","prompt":"Fluxul are trei pași. Pasul 2 a eșuat după ce pasul 1 a trimis deja un e-mail clientului. Ce se întâmplă dacă repeți tot fluxul fără protecție?","diagram":{"steps":["1. Trimite e-mail","2. Încasează plata","3. Confirmă comanda"],"fail":1},"payload":{"options":[{"t":"Clientul primește încă un e-mail.","ok":true},{"t":"Nimic, pasul 1 reușise deja.","ok":false,"why":"Fără protecție, pasul 1 rulează din nou."},{"t":"Plata se încasează de două ori, pentru că pasul 2 se reia.","ok":false,"why":"Plata nu reușise prima dată."},{"t":"Comanda se anulează automat.","ok":false,"why":"Nimic din flux nu anulează comanda."}]},"hint":"Ce pași reușiseră deja înainte de eșec?","explanation":"Reluarea întregului flux repetă și pașii reușiți. Fiecare pas cu efect extern are nevoie de protecție la repetare.","impact":"E-mailurile duble sunt jenante; încasările duble sunt incidente serioase. Același tipar le produce pe amândouă."},{"id":"mr-3","skill":"mm-retry","level":2,"type":"tradeoff","kind":"retry","tag":"p-partial","prompt":"Pasul „Încasează plata” a trimis cererea, dar răspunsul nu a mai venit (conexiunea a căzut). Ce știi sigur?","diagram":{"steps":["Cerere trimisă","? răspuns pierdut","Decizie"],"fail":1},"payload":{"options":[{"t":"Nu știi dacă a fost încasată.","ok":true},{"t":"Plata a eșuat, deci poți repeta liniștit.","ok":false,"why":"Lipsa răspunsului nu înseamnă eșec."},{"t":"Plata a reușit, deci mergi mai departe.","ok":false,"why":"Lipsa răspunsului nu înseamnă nici succes."},{"t":"Banca va anula automat cererea.","ok":false,"why":"Nu ai nicio garanție pentru asta."}]},"hint":"Ce înseamnă tăcerea?","explanation":"Răspunsul complet: Nu știi dacă plata a fost încasată sau nu. Un răspuns pierdut lasă trei posibilități: n-a ajuns, a ajuns și a eșuat, a ajuns și a reușit. Ai nevoie de o cale să verifici sau de o cheie care face repetarea sigură.","impact":"Tratarea tăcerii ca eșec duce la încasări duble; tratarea ei ca succes duce la comenzi neplătite."},{"id":"mr-4","skill":"mm-retry","level":2,"type":"flaw","kind":"assumption","tag":"p-double","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Butonul „Plătește” trimite cererea către bancă.","Utilizatorul apasă butonul o singură dată.","Banca răspunde de obicei în două secunde.","După răspuns afișăm confirmarea."],"bad":1},"hint":"Ce face un utilizator nerăbdător?","explanation":"Utilizatorii apasă de mai multe ori, mai ales când răspunsul întârzie. Sistemul trebuie să trateze apăsările repetate ca aceeași intenție.","impact":"Butoanele care declanșează plăți fără protecție la dublu-clic produc încasări duble exact când banca e lentă."},{"id":"mr-5","skill":"mm-retry","level":3,"type":"order","kind":"order","tag":"p-partial","prompt":"Ordonează etapele unui proces de comandă astfel încât o reîncercare să fie sigură.","diagram":{"steps":["Validare","Rezervare cheie unică","Persistență","Notificare","Compensare la eșec"]},"payload":{"steps":["Validezi cererea","Înregistrezi cheia unică a cererii","Persiști comanda","Trimiți notificarea, marcând-o ca trimisă","La eșec, compensezi pașii deja făcuți"]},"hint":"Cheia unică trebuie să existe înainte de orice efect.","explanation":"Validarea oprește devreme intrările greșite. Cheia unică permite recunoașterea repetărilor. Notificarea marcată evită dublarea, iar compensarea curăță efectele parțiale.","impact":"Ordinea pașilor decide dacă o cădere la mijloc lasă sistemul într-o stare care poate fi reparată automat."},{"id":"mr-6","skill":"mm-retry","level":4,"type":"diagnose","kind":"diagnose","tag":"p-double","prompt":"Simptom: în zilele cu multe erori de rețea, unii clienți primesc două confirmări și sunt taxați de două ori.","payload":{"hypotheses":[{"t":"Reîncercări fără cheie unică.","ok":true},{"t":"Clienții comandă intenționat de două ori când rețeaua e lentă.","ok":false,"why":"Nu explică legătura cu erorile de rețea."},{"t":"Banca e prea lentă în acele zile.","ok":false,"why":"Lentoarea singură nu dublează încasările."}],"tests":[{"t":"Cauți încasări duble din aceeași cerere.","ok":true},{"t":"Oprești toate reîncercările definitiv.","ok":false,"why":"E o schimbare, nu un test, și creează alte probleme."},{"t":"Măsori viteza paginii de plată.","ok":false,"why":"Nu verifică ipoteza."}]},"explanation":"Răspunsul complet: Reîncercările automate repetă încasarea fără o cheie care să le recunoască. Corelația cu erorile de rețea indică reîncercări. Două încasări din aceeași cerere confirmă lipsa idempotenței.","impact":"Testul potrivit separă cauza de coincidență înainte de schimbări riscante."},{"id":"mg-1","skill":"mm-model","level":1,"type":"tradeoff","kind":"invariant","tag":"p-coupling","prompt":"Un tabel are câte un rând pe produs vândut dintr-o comandă. Ce înseamnă un rând?","payload":{"options":[{"t":"O linie de produs dintr-o comandă.","ok":true},{"t":"O comandă întreagă, cu toate produsele ei.","ok":false,"why":"O comandă are mai multe linii, deci mai multe rânduri."},{"t":"Un client.","ok":false,"why":"Un client are multe comenzi."},{"t":"O zi de vânzări.","ok":false,"why":"O zi are multe comenzi."}]},"hint":"Granularitatea = ce reprezintă exact un rând.","explanation":"Granularitatea spune ce reprezintă un rând. Totalurile pe comandă cer agregarea liniilor.","impact":"Confuzia de granularitate e cauza clasică a totalurilor dublate sau a numărătorilor greșite."},{"id":"mg-2","skill":"mm-model","level":1,"type":"tradeoff","kind":"compromise","tag":"p-coupling","prompt":"Un singur program face validarea, calculul prețului, trimiterea e-mailului și arhivarea. Ce împărțire reduce cel mai mult riscul?","payload":{"options":[{"t":"Părți cu câte o responsabilitate.","ok":true},{"t":"Un program și mai mare, cu toate regulile într-un singur loc.","ok":false,"why":"Crește cuplajul și riscul la fiecare schimbare."},{"t":"Copii ale programului, câte una pe zi a săptămânii.","ok":false,"why":"Multiplici aceeași logică."},{"t":"Mutarea e-mailului la începutul programului.","ok":false,"why":"Schimbi ordinea, nu responsabilitățile."}]},"hint":"Ce se poate schimba independent?","explanation":"Răspunsul complet: Părți separate, fiecare cu o singură responsabilitate și intrări/ieșiri clare. Separarea responsabilităților face ca o schimbare la e-mail să nu atingă calculul prețului.","impact":"Părțile cu dependențe puține pot fi testate, reluate și înlocuite separat."},{"id":"mg-3","skill":"mm-model","level":2,"type":"flaw","kind":"assumption","tag":"p-coupling","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Avem un tabel cu comenzi și unul cu adresele clienților.","Unim comenzile cu adresele după client.","Fiecare client are o singură adresă.","Adunăm valoarea comenzilor pe oraș."],"bad":2},"hint":"Ce se întâmplă cu un client care s-a mutat?","explanation":"Un client poate avea mai multe adrese. Unirea cu toate adresele multiplică fiecare comandă și umflă totalurile.","impact":"Presupunerea „unu la unu” nescrisă ajunge în rapoarte ca cifre mai mari decât realitatea."},{"id":"mg-4","skill":"mm-model","level":2,"type":"tradeoff","kind":"invariant","tag":"p-coupling","prompt":"Regula: „Suma liniilor unei comenzi = totalul comenzii.” Ce operație o poate încălca fără să pară greșită?","payload":{"options":[{"t":"O unire cu relație unu-la-mai-mulți.","ok":true},{"t":"Sortarea liniilor după preț.","ok":false,"why":"Ordinea nu schimbă suma."},{"t":"Redenumirea unei coloane.","ok":false,"why":"Numele nu schimbă valorile."},{"t":"Filtrarea comenzilor dintr-o singură zi, înainte de calcul.","ok":false,"why":"Comenzile rămase își păstrează liniile."}]},"hint":"Care operație poate crește numărul de linii?","explanation":"Răspunsul complet: Unirea liniilor cu un tabel care are mai multe rânduri per comandă. O unire cu o relație „unul-la-mai-multe” multiplică liniile și rupe egalitatea dintre sumă și total.","impact":"Un invariant scris și verificat (suma = total) prinde multiplicarea imediat."},{"id":"mg-5","skill":"mm-model","level":3,"type":"tradeoff","kind":"compromise","tag":"p-premature","prompt":"O echipă vrea să modeleze de la început toate cazurile posibile, pentru „flexibilitate viitoare”. Livrarea întârzie. Ce compromis recomanzi?","payload":{"options":[{"t":"Modelezi clar nevoile actuale și lași puncte de extindere, fără să ghicești viitorul.","ok":true},{"t":"Continui până acoperi toate cazurile imaginabile.","ok":false,"why":"Complexitate plătită pentru nevoi care poate nu apar."},{"t":"Renunți la orice modelare și salvezi totul ca text.","ok":false,"why":"Simplitate falsă: complexitatea se mută la fiecare consumator."},{"t":"Copiezi modelul altei firme, așa cum este.","ok":false,"why":"Nevoile tale pot fi diferite."}]},"hint":"Flexibilitatea costă acum; beneficiul e incert.","explanation":"Simplitatea pentru ce știi azi, cu extensibilitate rezonabilă, bate de obicei modelele construite pentru scenarii ipotetice.","impact":"Optimizarea prematură pentru flexibilitate întârzie livrarea și face sistemul greu de înțeles."},{"id":"mg-6","skill":"mm-model","level":4,"type":"diagnose","kind":"diagnose","tag":"p-coupling","prompt":"Simptom: după ce s-a adăugat informația „adresa de livrare” în raport, vânzările pe oraș au crescut cu 18%, dar vânzările totale ale firmei nu s-au schimbat.","payload":{"hypotheses":[{"t":"Unirea cu adresele multiplică comenzi.","ok":true},{"t":"Vânzările reale au crescut în orașele mari.","ok":false,"why":"Totalul firmei ar fi crescut și el."},{"t":"Raportul vechi era greșit.","ok":false,"why":"Schimbarea coincide exact cu noua unire."}],"tests":[{"t":"Numeri rândurile per comandă, înainte și după.","ok":true},{"t":"Compari raportul cu cel al anului trecut, lună cu lună.","ok":false,"why":"Nu izolează schimbarea recentă."},{"t":"Elimini orașele mici din raport.","ok":false,"why":"Ascunde problema."}]},"explanation":"Răspunsul complet: Unirea cu adresele multiplică unele comenzi în raportul pe oraș. Totalul neschimbat și creșterea pe oraș după o unire nouă indică multiplicare. Numărarea rândurilor per comandă confirmă.","impact":"Un total de control pe un nivel superior (firma) e cel mai ieftin detector de multiplicare."},{"id":"mv-1","skill":"mm-invariant","level":1,"type":"tradeoff","kind":"invariant","tag":"p-invariant","prompt":"Regula: „Soldul unui cont nu poate deveni negativ.” Ce acțiune o încalcă?","payload":{"options":[{"t":"O retragere de 150 dintr-un cont cu 100.","ok":true},{"t":"O depunere de 150 într-un cont cu 0.","ok":false,"why":"Soldul crește."},{"t":"O retragere de 100 dintr-un cont cu 100.","ok":false,"why":"Soldul ajunge la 0, ceea ce e permis."},{"t":"Verificarea soldului.","ok":false,"why":"Citirea nu schimbă soldul."}]},"hint":"Calculează soldul după acțiune.","explanation":"Un invariant e o regulă care trebuie să rămână adevărată după orice operație. O verifici înainte de a aplica operația.","impact":"Invarianții verificați la intrare opresc erorile înainte să devină bani lipsă."},{"id":"mv-2","skill":"mm-invariant","level":1,"type":"tradeoff","kind":"invariant","tag":"p-missing","prompt":"La un ghișeu, regula este: „Fiecare persoană din coadă primește exact un număr de ordine.” Ce situație o încalcă?","payload":{"options":[{"t":"Același număr pentru două persoane.","ok":true},{"t":"O persoană așteaptă 20 de minute.","ok":false,"why":"Timpul de așteptare nu e regula."},{"t":"Coada are 30 de persoane.","ok":false,"why":"Lungimea cozii nu încalcă regula."},{"t":"Numărul 15 e chemat după 14.","ok":false,"why":"E ordinea normală."}]},"hint":"„Exact un” și „unic” sunt două părți ale regulii.","explanation":"Răspunsul complet: Aparatul se blochează și tipărește același număr pentru două persoane. Regula cere unicitate: două persoane cu același număr o rup, chiar dacă fiecare are „un număr”.","impact":"Duplicatele de identitate produc conflicte greu de rezolvat: cine e servit primul?"},{"id":"mv-3","skill":"mm-invariant","level":2,"type":"tradeoff","kind":"invariant","tag":"p-time","prompt":"Două retrageri de 80 dintr-un cont cu 100 vin în același moment. Fiecare verifică separat soldul (100) și trece. Ce s-a întâmplat cu regula „sold ≥ 0”?","payload":{"options":[{"t":"E încălcată: soldul final e −60, deși fiecare verificare a trecut.","ok":true},{"t":"E respectată, pentru că fiecare retragere a fost verificată.","ok":false,"why":"Verificările au văzut aceeași stare veche."},{"t":"A doua retragere se anulează automat.","ok":false,"why":"Nimic din enunț nu face asta."},{"t":"Soldul devine 20.","ok":false,"why":"Ar fi adevărat doar dacă s-ar aplica una singură."}]},"hint":"Ce sold a văzut a doua verificare?","explanation":"Concurența rupe invarianții verificați separat: verificarea și modificarea trebuie să fie o singură operație atomică.","impact":"Cazurile concurente apar rar în teste, dar sigur în producție, la volum mare."},{"id":"mv-4","skill":"mm-invariant","level":2,"type":"flaw","kind":"assumption","tag":"p-missing","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Calculăm media notelor fiecărui elev.","Împărțim suma notelor la numărul de note.","Fiecare elev are cel puțin o notă.","Afișăm media cu două zecimale."],"bad":2},"hint":"Ce se întâmplă cu un elev nou?","explanation":"Un elev fără note face împărțirea la zero sau produce o medie fără sens. Cazul gol trebuie tratat explicit.","impact":"Cazurile goale (zero elemente) sunt cea mai frecventă sursă de erori la calcule simple."},{"id":"mv-5","skill":"mm-invariant","level":3,"type":"order","kind":"order","tag":"p-invariant","prompt":"Ordonează pașii unei retrageri sigure, care respectă „sold ≥ 0” și când vin cereri simultane.","diagram":{"steps":["Blochează contul","Citește soldul","Verifică regula","Aplică retragerea","Eliberează contul"]},"payload":{"steps":["Obții accesul exclusiv la cont","Citești soldul curent","Verifici că soldul rămâne ≥ 0 după retragere","Aplici retragerea","Eliberezi accesul la cont"]},"hint":"Verificarea și modificarea trebuie protejate împreună.","explanation":"Accesul exclusiv în jurul citirii, verificării și modificării face operația atomică față de alte cereri.","impact":"Fără protecție comună, fiecare cerere „verificată” poate încălca regula în combinație cu alta."},{"id":"mv-6","skill":"mm-invariant","level":4,"type":"diagnose","kind":"diagnose","tag":"p-invariant","prompt":"Simptom: câteva conturi au sold negativ, deși fiecare retragere trece printr-o verificare „sold ≥ 0”. Apare doar la ore de vârf.","payload":{"hypotheses":[{"t":"Retrageri simultane văd același sold.","ok":true},{"t":"Verificarea are o greșeală de semn și lasă să treacă sumele negative.","ok":false,"why":"Ar produce probleme și în afara orelor de vârf."},{"t":"Clienții retrag mai mulți bani la vârf.","ok":false,"why":"Volumul singur nu ocolește verificarea."}],"tests":[{"t":"Cauți retrageri suprapuse în timp.","ok":true},{"t":"Dezactivezi verificarea și urmărești ce se întâmplă.","ok":false,"why":"Periculos și nu testează ipoteza."},{"t":"Măsori câte cereri pe minut sunt la vârf.","ok":false,"why":"Arată volumul, nu cauza."}]},"explanation":"Răspunsul complet: Retrageri simultane citesc același sold înainte ca prima să-l modifice. Legătura cu orele de vârf și verificarea care „trece” indică o problemă de concurență. Retragerile suprapuse în timp o confirmă.","impact":"Problemele care apar „doar la vârf” sunt de obicei de concurență; testul trebuie să caute suprapuneri, nu volume."},{"id":"mt-1","skill":"mm-tradeoff","level":1,"type":"tradeoff","kind":"compromise","tag":"p-premature","prompt":"O aplicație de știri trebuie să răspundă instant, iar o întârziere de un minut în actualizarea articolelor e acceptabilă. Ce principiu se potrivește?","payload":{"options":[{"t":"Disponibilitate și viteză, cu consistență eventuală.","ok":true},{"t":"Consistență strictă: nimeni nu vede articolul până nu e actualizat peste tot.","ok":false,"why":"Încetinește răspunsul fără beneficiu real aici."},{"t":"Oprirea aplicației la fiecare actualizare.","ok":false,"why":"Sacrifici disponibilitatea complet."},{"t":"Actualizarea manuală, o dată pe zi.","ok":false,"why":"Întârzierea depășește ce e acceptabil."}]},"hint":"Ce s-a spus că e acceptabil?","explanation":"Când o întârziere mică e acceptabilă, preferi disponibilitatea și viteza, acceptând că datele devin consistente după scurt timp.","impact":"Alegerea consistenței stricte unde nu e nevoie costă viteză și disponibilitate."},{"id":"mt-2","skill":"mm-tradeoff","level":1,"type":"tradeoff","kind":"compromise","tag":"p-premature","prompt":"Un sistem de plăți nu are voie să accepte două plăți cu aceleași fonduri. Ce principiu se potrivește?","payload":{"options":[{"t":"Consistența are prioritate.","ok":true},{"t":"Viteza are prioritate; corecturile se fac lunar.","ok":false,"why":"Plățile duble sunt pierderi reale."},{"t":"Fiecare server decide independent.","ok":false,"why":"Exact situația care permite dublarea."},{"t":"Acceptă tot și anulează dublurile manual.","ok":false,"why":"Reactiv și costisitor."}]},"hint":"Ce costă mai mult: o secundă în plus sau bani dublați?","explanation":"Răspunsul complet: Consistența are prioritate, chiar cu un răspuns ceva mai lent. Unde o greșeală e ireversibilă și scumpă, consistența bate viteza.","impact":"Același sistem poate avea părți cu priorități diferite: știri rapide, plăți consistente."},{"id":"mt-3","skill":"mm-tradeoff","level":2,"type":"flaw","kind":"assumption","tag":"p-premature","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Raportul lunar durează 4 minute.","Vrem să-l facem să ruleze în 4 secunde.","Utilizatorii au nevoie de el instant.","Îl citesc o dată pe lună, la ședința de bilanț."],"bad":2},"hint":"Ce spun ultimele două propoziții, puse împreună?","explanation":"Un raport citit lunar nu are nevoie de răspuns instant. Optimizarea lui e muncă fără beneficiu.","impact":"Optimizarea prematură consumă timp și adaugă complexitate unde nu există o nevoie reală."},{"id":"mt-4","skill":"mm-tradeoff","level":2,"type":"tradeoff","kind":"compromise","tag":"p-time","prompt":"Procesezi comenzi. Le poți trimite una câte una (fiecare imediat) sau în loturi de 1000 (la fiecare minut). Ce câștigi și ce pierzi cu loturile?","payload":{"options":[{"t":"Câștigi debit (mai multe pe secundă), pierzi latență (fiecare așteaptă lotul).","ok":true},{"t":"Câștigi și debit, și latență.","ok":false,"why":"Loturile adaugă așteptare."},{"t":"Pierzi debit, câștigi latență.","ok":false,"why":"E invers."},{"t":"Nu se schimbă nimic.","ok":false,"why":"Lotul schimbă clar compromisul."}]},"hint":"Cât așteaptă prima comandă dintr-un lot?","explanation":"Loturile împart costul fix pe mai multe elemente (debit mai mare), dar fiecare element așteaptă formarea lotului (latență mai mare).","impact":"Mărimea lotului e un buton de reglaj între latență și debit; alegerea ei pornește de la cerință."},{"id":"mt-5","skill":"mm-tradeoff","level":3,"type":"tradeoff","kind":"compromise","tag":"p-coupling","prompt":"Pentru un flux de aprobări cu 3 echipe, ai două variante: fiecare echipă își notifică direct următoarea (decuplat, greu de urmărit) sau un coordonator central (vizibil, dar punct comun). Ce alegi când auditul e esențial?","payload":{"options":[{"t":"Coordonatorul central.","ok":true},{"t":"Notificările directe, fiindcă decuplarea e mereu mai bună.","ok":false,"why":"„Mereu” ignoră cerința de audit."},{"t":"Fără niciun flux formal; echipele se înțeleg.","ok":false,"why":"Elimină exact ce cere auditul."},{"t":"Ambele variante în paralel.","ok":false,"why":"Dublezi sursele de adevăr."}]},"hint":"Cerința decide compromisul.","explanation":"Răspunsul complet: Coordonatorul central, care dă vizibilitate completă asupra fluxului. Decuplarea reduce dependențele, dar ascunde fluxul; vizibilitatea centrală costă un punct comun. Auditul înclină balanța spre vizibilitate.","impact":"Niciun principiu nu e „mereu bun”; contextul (aici auditul) alege."},{"id":"mt-6","skill":"mm-tradeoff","level":4,"type":"diagnose","kind":"diagnose","tag":"p-time","prompt":"Simptom: după trecerea la loturi de 1000, clienții se plâng că confirmările vin cu până la un minut întârziere, deși sistemul procesează de 5 ori mai mult.","payload":{"hypotheses":[{"t":"Așteptarea formării lotului.","ok":true},{"t":"Serverele sunt supraîncărcate de volumul de cinci ori mai mare.","ok":false,"why":"Debitul a crescut de 5 ori, deci capacitatea e suficientă."},{"t":"Clienții au conexiuni lente.","ok":false,"why":"Nu explică legătura cu schimbarea în loturi."}],"tests":[{"t":"Măsori separat așteptarea și procesarea.","ok":true},{"t":"Dublezi numărul de servere.","ok":false,"why":"E o schimbare scumpă, nu un test."},{"t":"Ceri clienților să reîncerce.","ok":false,"why":"Nu testează nimic."}]},"explanation":"Răspunsul complet: Întârzierea vine din așteptarea formării lotului, nu din lentoare. Debit mai mare și latență mai mare după loturi e exact compromisul așteptat. Măsurarea separată a așteptării confirmă.","impact":"Înțelegerea compromisului evită „reparații” care adaugă resurse fără să atingă cauza."},{"id":"mo-1","skill":"mm-observe","level":1,"type":"tradeoff","kind":"invariant","tag":"p-observe","prompt":"Un proces nocturn nu a pornit. Nu a dat nicio eroare. Ce semnal te-ar fi anunțat?","payload":{"options":[{"t":"O alertă dacă rezultatul nu apare la timp.","ok":true},{"t":"O alertă la erori.","ok":false,"why":"Un proces care nu pornește nu produce erori."},{"t":"Un raport lunar de activitate.","ok":false,"why":"Prea târziu."},{"t":"Verificarea manuală, când își amintește cineva.","ok":false,"why":"Nu e un semnal."}]},"hint":"Cum observi ceva care lipsește?","explanation":"Răspunsul complet: O alertă când rezultatul așteptat nu apare până la o oră limită. Absența unui eveniment se observă doar dacă aștepți explicit prezența lui, cu un termen.","impact":"Multe incidente sunt „lipsa” a ceva; alertele doar pe erori nu le văd."},{"id":"mo-2","skill":"mm-observe","level":1,"type":"tradeoff","kind":"compromise","tag":"p-observe","prompt":"Un utilizator spune: „Ieri a mers greu.” Ce informație te ajută cel mai mult să afli ce s-a întâmplat?","payload":{"options":[{"t":"Înregistrări cu durata fiecărui pas, cu momentul și identitatea cererii.","ok":true},{"t":"Numărul total de utilizatori de ieri.","ok":false,"why":"Nu spune unde a fost lent."},{"t":"Părerea altor utilizatori.","ok":false,"why":"Subiectivă și incompletă."},{"t":"Versiunea aplicației.","ok":false,"why":"Utilă, dar insuficientă singură."}]},"hint":"Ai nevoie de unde, când și pentru ce cerere.","explanation":"Durata pe pași, cu moment și identitate, îți permite să urmărești o cerere de la un capăt la altul.","impact":"Fără urme pe pași, diagnosticul devine ghicit."},{"id":"mo-3","skill":"mm-observe","level":2,"type":"flaw","kind":"assumption","tag":"p-observe","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Procesul a terminat cu „succes”.","Deci datele de azi sunt complete.","Raportul folosește datele de azi.","Raportul e trimis conducerii."],"bad":1},"hint":"„Succes” spune ce despre volum?","explanation":"Un proces poate termina cu succes procesând doar o parte din date (sursă incompletă). Completitudinea se verifică separat.","impact":"Succesul tehnic nu e corectitudine; un raport cu 40% din date poate pleca la conducere fără nicio eroare."},{"id":"mo-4","skill":"mm-observe","level":2,"type":"tradeoff","kind":"invariant","tag":"p-observe","prompt":"Zilnic se încarcă aproximativ 10 000 de comenzi. Azi s-au încărcat 4 000, fără erori. Ce regulă de alertare ar fi prins problema?","payload":{"options":[{"t":"Volumul zilei sub jumătate din valoarea obișnuită.","ok":true},{"t":"Volumul zilei egal cu zero.","ok":false,"why":"Ratează încărcările parțiale."},{"t":"Orice eroare raportată de proces în timpul încărcării.","ok":false,"why":"Nu au existat erori."},{"t":"Durata procesului peste o oră.","ok":false,"why":"Un volum mic durează mai puțin, nu mai mult."}]},"hint":"Compari cu ce e normal.","explanation":"Regulile relative la normal (de exemplu mediana zilelor recente) prind și lipsurile parțiale.","impact":"Încărcările parțiale sunt mai periculoase decât cele lipsă, pentru că par plauzibile."},{"id":"mo-5","skill":"mm-observe","level":3,"type":"order","kind":"order","tag":"p-observe","prompt":"Un rezultat final e greșit. Ordonează pașii de diagnostic, fără să ghicești.","payload":{"steps":["Confirmi simptomul cu date concrete","Găsești primul punct din flux unde datele devin greșite","Formulezi o ipoteză pentru acel punct","Testezi ipoteza pe cazuri afectate și neafectate","Repari și verifici că simptomul a dispărut"]},"hint":"Mergi de la simptom spre sursă, apoi testezi.","explanation":"Localizarea primului punct greșit restrânge căutarea; testul pe cazuri afectate și neafectate separă cauza de coincidență.","impact":"Diagnosticul ordonat scurtează incidentele și evită reparații care mută problema."},{"id":"mo-6","skill":"mm-observe","level":4,"type":"diagnose","kind":"diagnose","tag":"p-observe","prompt":"Simptom: un raport arată vânzări zero pentru o singură regiune, din ziua în care s-a redenumit regiunea în sistemul sursă.","payload":{"hypotheses":[{"t":"Filtrul folosește vechiul nume.","ok":true},{"t":"Regiunea chiar nu a mai vândut nimic din acea zi.","ok":false,"why":"Coincidența exactă cu redenumirea o face improbabilă."},{"t":"Raportul e lent.","ok":false,"why":"Lentoarea nu produce zero."}],"tests":[{"t":"Cauți vânzările după noul nume.","ok":true},{"t":"Repornești raportul.","ok":false,"why":"Nu verifică filtrul."},{"t":"Compari regiunea cu toate celelalte regiuni, zi cu zi.","ok":false,"why":"Nu testează ipoteza numelui."}]},"explanation":"Răspunsul complet: Raportul filtrează după vechiul nume al regiunii. O schimbare de nume în sursă și un filtru care o folosește dau exact „zero de la o dată”. Căutarea după noul nume confirmă.","impact":"Filtrele după nume (în loc de identificatori stabili) se rup la prima redenumire."},{"id":"me-1","skill":"mm-evolve","level":1,"type":"tradeoff","kind":"invariant","tag":"p-compat","prompt":"Un formular trimite datele către trei aplicații. Vrei să adaugi un câmp nou. Ce schimbare e cea mai sigură pentru aplicațiile existente?","payload":{"options":[{"t":"Un câmp nou, opțional.","ok":true},{"t":"Redenumești un câmp existent.","ok":false,"why":"Aplicațiile vechi nu mai găsesc câmpul."},{"t":"Schimbi tipul unui câmp existent.","ok":false,"why":"Aplicațiile vechi pot interpreta greșit valoarea."},{"t":"Ștergi un câmp puțin folosit.","ok":false,"why":"„Puțin” nu înseamnă „deloc”."}]},"hint":"Ce schimbare nu obligă pe nimeni să se schimbe?","explanation":"Răspunsul complet: Adaugi un câmp opțional; cei vechi îl pot ignora. Adăugarea opțională e compatibilă înapoi: cititorii vechi continuă să funcționeze.","impact":"Schimbările compatibile pot fi livrate independent; cele incompatibile cer coordonare cu toți consumatorii."},{"id":"me-2","skill":"mm-evolve","level":1,"type":"tradeoff","kind":"compromise","tag":"p-compat","prompt":"Vrei să redenumești un câmp folosit de alte echipe. Ce abordare e mai sigură?","payload":{"options":[{"t":"Adaugi câmpul nou, păstrezi un timp și câmpul vechi, anunți și apoi retragi.","ok":true},{"t":"Redenumești peste noapte și anunți dimineața.","ok":false,"why":"Echipele afectate află după ce s-au stricat."},{"t":"Nu redenumești niciodată nimic.","ok":false,"why":"Prea rigid; sistemul nu mai poate evolua."},{"t":"Lași fiecare echipă să ghicească noul nume.","ok":false,"why":"Garantat incomplet."}]},"hint":"Perioada de tranziție.","explanation":"Expand–contract: extinzi (nou + vechi), migrezi consumatorii, apoi restrângi (scoți vechiul).","impact":"Tiparul expand–contract face posibile schimbări mari fără opriri sau incidente."},{"id":"me-3","skill":"mm-evolve","level":2,"type":"flaw","kind":"assumption","tag":"p-compat","prompt":"Atinge propoziția care ascunde o presupunere falsă.","payload":{"lines":["Schimbăm formatul datei din „zi/lună/an” în „an-lună-zi”.","Aplicația noastră citește noul format.","Toate aplicațiile care citesc datele noastre se actualizează în aceeași zi.","Datele vechi rămân în formatul vechi."],"bad":2},"hint":"Controlezi tu toți cititorii?","explanation":"Consumatorii au propriile calendare. Presupunerea că se actualizează simultan e aproape mereu falsă.","impact":"Schimbările care cer actualizare simultană a tuturor sunt cele care produc incidente în lanț."},{"id":"me-4","skill":"mm-evolve","level":2,"type":"tradeoff","kind":"invariant","tag":"p-compat","prompt":"Datele vechi au formatul vechi, cele noi formatul nou. Un cititor trebuie să le citească pe amândouă. Ce regulă îl ajută?","payload":{"options":[{"t":"Versiunea de format, pe fiecare înregistrare.","ok":true},{"t":"Cititorul ghicește formatul după aspectul fiecărei valori.","ok":false,"why":"Unele valori arată la fel în ambele formate (de exemplu 03/04)."},{"t":"Se convertesc toate datele vechi peste noapte.","ok":false,"why":"Poate fi util, dar nu ajută consumatorii în tranziție."},{"t":"Se citește doar formatul nou.","ok":false,"why":"Pierzi datele vechi."}]},"hint":"„03/04” e martie sau aprilie?","explanation":"Răspunsul complet: Fiecare înregistrare spune ce versiune de format are. Versiunea explicită elimină ghicitul; cititorul aplică regula potrivită fiecărei înregistrări.","impact":"Ghicirea formatului produce erori tăcute, de exemplu zile și luni inversate."},{"id":"me-5","skill":"mm-evolve","level":3,"type":"order","kind":"order","tag":"p-compat","prompt":"Ordonează pașii pentru înlocuirea sigură a unui câmp folosit de alte echipe.","diagram":{"steps":["Extinde","Migrează","Verifică","Restrânge"]},"payload":{"steps":["Adaugi câmpul nou alături de cel vechi","Scrii valorile în ambele câmpuri","Muți consumatorii pe câmpul nou","Verifici că nimeni nu mai citește câmpul vechi","Elimini câmpul vechi"]},"hint":"Extinde, migrează, verifică, restrânge.","explanation":"Ordinea expand–contract păstrează sistemul funcțional la fiecare pas.","impact":"Eliminarea câmpului vechi înaintea verificării e pasul care strică de obicei un consumator uitat."},{"id":"me-6","skill":"mm-evolve","level":4,"type":"diagnose","kind":"diagnose","tag":"p-compat","prompt":"Simptom: după o actualizare, un singur raport arată date din viitor (de exemplu 2026-12-05 pentru o comandă din 12 mai).","payload":{"hypotheses":[{"t":"Raportul interpretează noul format de dată ca pe cel vechi, inversând ziua și luna.","ok":true},{"t":"Ceasul serverului e greșit.","ok":false,"why":"Ar afecta toate rapoartele."},{"t":"Clienții au comandat în avans.","ok":false,"why":"Nu explică legătura cu actualizarea."}],"tests":[{"t":"Compari valorile originale cu cele afișate.","ok":true},{"t":"Reinstalezi raportul.","ok":false,"why":"Nu verifică interpretarea formatului."},{"t":"Ștergi comenzile din viitor.","ok":false,"why":"Distrugi date corecte."}]},"explanation":"„Un singur raport” după o schimbare de format indică un consumator neactualizat. Comparația cu valorile originale arată inversarea.","impact":"Consumatorii uitați se descoperă prin simptome ciudate; o listă a consumatorilor previne asta."}],"cards":[{"id":"rc-sn-1","skill":"sql-null","category":"cheat_sheet","title":"NULL în 6 reguli","body":"- `x = NULL` → UNKNOWN; folosești `IS NULL` / `IS NOT NULL`.\n- `IS DISTINCT FROM` compară tratând NULL ca valoare.\n- `COUNT(*)` numără rânduri; `COUNT(col)`, `SUM`, `AVG` ignoră NULL.\n- `NOT IN (listă cu NULL)` → niciun rând; folosești `NOT EXISTS`.\n- `COALESCE(col, valoare)` înlocuiește NULL la afișare sau calcul.\n- În join, cheile NULL nu se potrivesc între ele."},{"id":"rc-sn-2","skill":"sql-null","category":"anti_pattern","title":"Join care multiplică rânduri","body":"**Simptom:** totaluri prea mari după un join.\n\n**Cauză:** tabelul din dreapta are mai multe rânduri pe cheie (1:N).\n\n**Verificare:** `SELECT cheie, COUNT(*) FROM dreapta GROUP BY cheie HAVING COUNT(*) > 1`.\n\n**Remediu:** agregi sau filtrezi fiecare parte la granularitatea țintă înainte de join."},{"id":"rc-dm-1","skill":"delta-merge","category":"cheat_sheet","title":"MERGE, RESTORE, VACUUM","body":"- `MERGE INTO t USING s ON cheie WHEN MATCHED ... WHEN NOT MATCHED ...`\n- Sursa trebuie să aibă un singur rând pe cheie (deduplici cu `row_number()` și ordine completă).\n- `DESCRIBE HISTORY t` → versiuni; `SELECT ... VERSION AS OF n` → citire.\n- `RESTORE TABLE t TO VERSION AS OF n` → revenire, ca versiune nouă.\n- `VACUUM` șterge fișierele mai vechi decât retenția (implicit 7 zile)."},{"id":"rc-dm-2","skill":"delta-merge","category":"incident","title":"Incident: VACUUM cu retenție 0","body":"**Ce s-a întâmplat:** pentru a elibera spațiu, cineva a dezactivat verificarea de retenție și a rulat `VACUUM RETAIN 0 HOURS`. A doua zi, un job a suprascris greșit tabelul.\n\n**Efect:** `RESTORE` a eșuat; fișierele versiunilor vechi nu mai existau.\n\n**Lecția:** retenția se alege din cerințele de recuperare și audit; protecția de retenție nu se dezactivează în producție."},{"id":"rc-sp-1","skill":"spark-perf","category":"cheat_sheet","title":"Shuffle și join-uri","body":"- **Înguste (fără shuffle):** `select`, `filter`, `withColumn`, `union`.\n- **Largi (cu shuffle):** `groupBy`, `join` (fără broadcast), `distinct`, `orderBy`, `repartition`.\n- **Broadcast:** pentru tabele mici (zeci de MB); `broadcast(df)`.\n- **Skew:** mediană mică, maxim uriaș la durata taskurilor → AQE skew join, salting.\n- **Fișiere mici:** nu partiționa pe coloane cu cardinalitate mare; compactează."},{"id":"rc-sp-2","skill":"spark-perf","category":"anti_pattern","title":"Partiționare pe ID","body":"**Simptom:** milioane de directoare și fișiere mici, citiri lente.\n\n**Cauză:** `partitionBy('client_id')` sau altă coloană cu cardinalitate mare.\n\n**Remediu:** partiționezi pe dată (sau deloc pentru tabele mici) și folosești clustering pentru filtrele pe ID."},{"id":"rc-ss-1","skill":"stream-state","category":"cheat_sheet","title":"Stream-uri cu stare","body":"- Watermark = maximul event_time văzut − întârzierea permisă.\n- Evenimentele mai vechi decât watermark-ul pot fi ignorate.\n- Agregări în append și deduplicări au nevoie de watermark.\n- Fiecare stream: checkpoint propriu, stabil.\n- `foreachBatch` = cel puțin o dată; idempotența dă „exact o dată”.\n- `trigger(availableNow=True)` = procesare incrementală, apoi oprire."},{"id":"rc-ss-2","skill":"stream-state","category":"incident","title":"Incident: checkpoint partajat","body":"**Ce s-a întâmplat:** două stream-uri copiate din același șablon au păstrat aceeași cale de checkpoint.\n\n**Efect:** loturi sărite și dublate, observate după două săptămâni la reconcilierea lunară.\n\n**Lecția:** calea de checkpoint e parte din identitatea stream-ului; o generezi din numele tabelului țintă și o verifici în code review."},{"id":"rc-uc-1","skill":"uc-access","category":"cheat_sheet","title":"Privilegii Unity Catalog","body":"- Citire: `USE CATALOG` + `USE SCHEMA` + `SELECT`.\n- Scriere: plus `MODIFY`.\n- Privilegiile se moștenesc în jos în ierarhie.\n- Fișiere brute: `READ FILES` pe external location sau volume.\n- Proprietar: grup sau service principal.\n- Rânduri și coloane: row filters și column masks pe tabel."},{"id":"rc-uc-2","skill":"uc-access","category":"anti_pattern","title":"ALL PRIVILEGES pe schemă","body":"**Simptom:** un grup de raportare poate șterge sau modifica tabele.\n\n**Cauză:** `GRANT ALL PRIVILEGES ON SCHEMA` dat „ca să meargă”.\n\n**Remediu:** acorzi exact privilegiile necesare și verifici periodic cu `SHOW GRANTS`."},{"id":"rc-po-1","skill":"pipeline-ops","category":"cheat_sheet","title":"Retry și idempotență","body":"- **Reîncerci:** 429, 5xx, timeout, cu backoff exponențial și jitter.\n- **Nu reîncerci:** 400, 401, 403, 404, erori de schemă sau de sintaxă.\n- **Scriere idempotentă:** MERGE pe cheie sau suprascrierea partiției (`replaceWhere`).\n- **Append + retry** = risc de duplicate.\n- **Alertă pe prospețime și volum**, nu doar pe erori."},{"id":"rc-po-2","skill":"pipeline-ops","category":"incident","title":"Incident: încărcare parțială","body":"**Ce s-a întâmplat:** API-ul sursă a întors doar prima pagină din cauza unui token expirat la jumătatea extracției; jobul a raportat succes.\n\n**Efect:** raportul zilei a arătat 40% din vânzări; nimeni n-a observat până la reconciliere.\n\n**Lecția:** verifici volumul față de zilele anterioare și completitudinea paginării înainte de publicare."},{"id":"mm-card-1","skill":"mm-contract","category":"model","title":"Contractul","body":"**Pe scurt.** Un contract spune ce primește un sistem, ce promite să întoarcă și ce face când intrarea nu respectă regulile.\n\n**Regula de aur.** Verifici intrarea la graniță și o respingi clar dacă nu respectă contractul.\n\n**Când ajută.** Orice graniță între părți: oameni, echipe, sisteme.\n\n**Când nu ajută.** Când contractul nu e scris: atunci fiecare parte presupune altceva.\n\n**Întreabă-te.** Ce se întâmplă cu o intrare care lipsește, e goală sau are alt format?"},{"id":"mm-card-2","skill":"mm-identity","category":"model","title":"Identitate, stare și timp","body":"**Pe scurt.** Identitatea spune ce e același lucru în timp. Starea e ce știi despre el acum. Timpul are trei momente: producere, sosire, procesare.\n\n**Regula de aur.** Decizi starea după momentul producerii sau după o secvență, nu după ordinea sosirii.\n\n**Când ajută.** Evenimente care vin din locuri diferite sau cu întârzieri.\n\n**Când nu ajută.** Când identitatea nu e stabilă (de exemplu după nume).\n\n**Întreabă-te.** Ce face unic acest lucru? Ce se întâmplă dacă mesajele vin în altă ordine?"},{"id":"mm-card-3","skill":"mm-retry","category":"model","title":"Idempotența","body":"**Pe scurt.** O operație idempotentă dă același rezultat final oricâte ori o repeți.\n\n**Regula de aur.** Orice pas cu efect extern are o cheie care recunoaște repetarea.\n\n**Când ajută.** Reîncercări automate, rețele nesigure, utilizatori care apasă de două ori.\n\n**Când nu ajută.** Singură, nu repară o operație greșită; doar o face sigură la repetare.\n\n**Întreabă-te.** Ce se întâmplă dacă acest pas rulează de două ori?"},{"id":"mm-card-4","skill":"mm-model","category":"model","title":"Granularitatea","body":"**Pe scurt.** Granularitatea spune ce reprezintă exact o unitate (un rând, un mesaj, o linie).\n\n**Regula de aur.** Aduci părțile la aceeași granularitate înainte să le combini.\n\n**Când ajută.** Orice combinare de liste, tabele sau rapoarte.\n\n**Când nu ajută.** Când granularitatea nu e scrisă: fiecare o presupune diferit.\n\n**Întreabă-te.** Ce reprezintă exact un rând aici? Poate un rând din stânga să se potrivească cu mai multe din dreapta?"},{"id":"mm-card-5","skill":"mm-invariant","category":"model","title":"Invarianții","body":"**Pe scurt.** Un invariant e o regulă care trebuie să rămână adevărată după orice operație.\n\n**Regula de aur.** Verifici regula și aplici modificarea într-un singur pas protejat.\n\n**Când ajută.** Solduri, stocuri, stări finale, unicitate.\n\n**Când nu ajută.** Când regula e verificată separat de modificare și vin cereri simultane.\n\n**Întreabă-te.** Ce regulă nu are voie să se rupă niciodată? Ce cerere simultană ar rupe-o?"},{"id":"mm-card-6","skill":"mm-tradeoff","category":"model","title":"Compromisurile","body":"**Pe scurt.** Aproape fiecare alegere tehnică câștigă ceva și pierde altceva.\n\n**Regula de aur.** Cerința decide: întâi spui ce contează mai mult, apoi alegi.\n\n**Când ajută.** Viteză vs. corectitudine, simplu vs. flexibil, decuplat vs. vizibil.\n\n**Când nu ajută.** Când „cel mai bun” e decis fără context.\n\n**Întreabă-te.** Ce pierd cu această alegere și este acceptabil aici?"},{"id":"mm-card-7","skill":"mm-observe","category":"model","title":"Observabilitatea","body":"**Pe scurt.** Un sistem observabil îți spune ce s-a întâmplat, unde și când, fără să ghicești.\n\n**Regula de aur.** Măsori și ce lipsește (volum, prospețime), nu doar erorile.\n\n**Când ajută.** Diagnostic, alertare, încredere în rezultate.\n\n**Când nu ajută.** Când ai date, dar nu și o întrebare clară.\n\n**Întreabă-te.** Cum aș afla, fără să întreb pe nimeni, că acest pas a mers prost?"},{"id":"mm-card-8","skill":"mm-evolve","category":"model","title":"Compatibilitatea","body":"**Pe scurt.** O schimbare compatibilă nu obligă pe nimeni să se schimbe în același timp.\n\n**Regula de aur.** Extinzi, migrezi, verifici, apoi restrângi.\n\n**Când ajută.** Formate, câmpuri, interfețe folosite de alții.\n\n**Când nu ajută.** Când nu știi cine depinde de tine.\n\n**Întreabă-te.** Cine citește asta și ce s-ar strica dacă se schimbă azi?"},{"id":"mm-pit-1","skill":"mm-identity","category":"pitfall","title":"Presupui că ordinea e garantată","body":"Mesajele, cererile și evenimentele pot sosi în altă ordine decât s-au produs.\n\n**Semn:** o stare „se întoarce” la una anterioară.\n\n**Apărare:** moment de producere sau număr de secvență."},{"id":"mm-pit-2","skill":"mm-invariant","category":"pitfall","title":"Uiți de valorile lipsă și de cazurile goale","body":"Lipsa nu e zero, iar o listă goală nu e o eroare.\n\n**Semn:** împărțiri la zero, totaluri ciudate, rânduri dispărute.\n\n**Apărare:** decizi explicit ce se întâmplă cu „gol” și „lipsă”."},{"id":"mm-pit-3","skill":"mm-retry","category":"pitfall","title":"Efecte secundare ascunse","body":"Un pas care pare că „doar citește” trimite și un mesaj sau modifică ceva.\n\n**Semn:** reluarea unui calcul produce notificări sau înregistrări noi.\n\n**Apărare:** separi pașii care citesc de cei care schimbă lumea."},{"id":"mm-pit-4","skill":"mm-retry","category":"pitfall","title":"Execuția dublă","body":"Orice poate rula de două ori: reîncercări, dublu-clic, reporniri.\n\n**Semn:** duplicate care apar „din când în când”.\n\n**Apărare:** chei de idempotență și operații care pot fi repetate."},{"id":"mm-pit-5","skill":"mm-model","category":"pitfall","title":"Cuplajul strâns","body":"Când o parte nu poate fi schimbată fără să atingi alte cinci.\n\n**Semn:** o schimbare mică cere coordonare cu multe echipe.\n\n**Apărare:** intrări și ieșiri clare, responsabilități separate."},{"id":"mm-pit-6","skill":"mm-tradeoff","category":"pitfall","title":"Optimizarea prematură","body":"Complexitate plătită pentru o performanță de care nu ai nevoie.\n\n**Semn:** cod greu de înțeles pentru un câștig pe care nu-l observă nimeni.\n\n**Apărare:** măsori întâi și optimizezi doar unde cerința o cere."},{"id":"mm-pit-7","skill":"mm-identity","category":"pitfall","title":"Ignori timpul și întârzierile","body":"Nimic nu e instant: rețele, cozi și oameni introduc întârzieri.\n\n**Semn:** rapoarte care se schimbă după publicare.\n\n**Apărare:** ferestre de întârziere și rezultate marcate provizoriu sau final."},{"id":"mm-pit-8","skill":"mm-observe","category":"pitfall","title":"Diagnostichezi prin ghicit","body":"Schimbi lucruri până dispare simptomul.\n\n**Semn:** problema revine sau apare în altă parte.\n\n**Apărare:** simptom, punctul unde apare, ipoteză, test, reparație."},{"id":"mm-mat-1","skill":"mm-tradeoff","category":"matrix","title":"Viteză vs. corectitudine","body":"| Alegi | Când | Plătești |\n|---|---|---|\n| Viteză | întârzierea mică e acceptabilă | date temporar inconsistente |\n| Corectitudine | greșeala e ireversibilă | răspuns mai lent |\n| Provizoriu + final | ambele contează | două versiuni de explicat |"},{"id":"mm-mat-2","skill":"mm-tradeoff","category":"matrix","title":"Simplu vs. flexibil","body":"| Alegi | Când | Plătești |\n|---|---|---|\n| Simplu | nevoia e clară azi | refaci dacă nevoia se schimbă mult |\n| Flexibil | schimbările sunt sigure și frecvente | complexitate de la început |\n| Simplu + extensibil | incertitudine moderată | disciplină în proiectare |"},{"id":"mm-mat-3","skill":"mm-model","category":"matrix","title":"Decuplat vs. vizibil","body":"| Alegi | Când | Plătești |\n|---|---|---|\n| Decuplat | părți care evoluează separat | fluxul e greu de urmărit |\n| Coordonat central | audit și vizibilitate | punct comun de dependență |\n| Decuplat + jurnal comun | ambele contează | efort de urmărire |"},{"id":"mm-scn-1","skill":"mm-invariant","category":"scenario","title":"Coada la ghișeu","body":"Un aparat dă numere de ordine. Doi oameni apasă simultan.\n\n**Gândește:** cum garantezi numere unice? Ce se întâmplă dacă aparatul repornește? Ce face un om care a pierdut bonul?\n\n**Concepte:** identitate, invarianți, concurență."},{"id":"mm-scn-2","skill":"mm-contract","category":"scenario","title":"Fișa de inventar","body":"Un magazin ține o fișă: produs, cantitate, ultima actualizare. Mai mulți angajați o completează.\n\n**Gândește:** ce înseamnă un câmp gol? Cine are ultima versiune? Ce se întâmplă cu două corecturi simultane?\n\n**Concepte:** contracte, valori lipsă, stare și timp."},{"id":"mm-scn-3","skill":"mm-retry","category":"scenario","title":"Sistemul de rezervări","body":"Un client rezervă o masă. Confirmarea întârzie, iar el apasă din nou.\n\n**Gândește:** câte rezervări există acum? Cum recunoști a doua apăsare? Ce se întâmplă dacă restaurantul anulează?\n\n**Concepte:** idempotență, compensare, identitate."},{"id":"mm-scn-4","skill":"mm-tradeoff","category":"scenario","title":"Fluxul de aprobări","body":"O cerere trece prin trei aprobări: șef, financiar, director.\n\n**Gândește:** ce se întâmplă dacă un aprobator e în concediu? Cine vede unde e cererea? Se poate aproba în paralel?\n\n**Concepte:** compromisuri, observabilitate, dependențe."},{"id":"mm-scn-5","skill":"mm-evolve","category":"scenario","title":"Formularul care se schimbă","body":"Un formular folosit de trei departamente primește un câmp nou și unul redenumit.\n\n**Gândește:** cine trebuie anunțat? Ce se întâmplă cu formularele vechi, deja completate? Când poți șterge câmpul vechi?\n\n**Concepte:** compatibilitate, evoluție, contracte."},{"id":"mm-scn-6","skill":"mm-observe","category":"scenario","title":"Livrarea care nu a sosit","body":"Un colet „livrat” în sistem nu a ajuns la client.\n\n**Gândește:** ce înregistrări ai la fiecare pas? Care e primul pas în care datele nu se potrivesc cu realitatea? Cum verifici fără să ghicești?\n\n**Concepte:** observabilitate, diagnostic, stare."}],"tags":{"null-logic":"Logica NULL","join-fanout":"Join-uri care multiplică rânduri","merge-dup":"Duplicate la scriere","vacuum-retention":"Retenție și VACUUM","shuffle":"Shuffle","broadcast":"Broadcast","skew":"Skew","small-files":"Fișiere mici","watermark":"Watermark","checkpoint":"Checkpoint","exactly-once":"Efect exact o dată","uc-hierarchy":"Ierarhia de privilegii","uc-ownership":"Proprietari","uc-row-filter":"Filtre pe rânduri","retry":"Reîncercări","freshness":"Prospețime și volum","p-order":"Ordinea nu e garantată","p-missing":"Valori lipsă și cazuri goale","p-side":"Efecte secundare ascunse","p-double":"Execuția dublă","p-coupling":"Cuplajul strâns","p-premature":"Optimizarea prematură","p-time":"Timpul și întârzierile","p-contract":"Contractul încălcat","p-identity":"Identitatea greșită","p-invariant":"Invarianța ignorată","p-partial":"Eșecul parțial","p-compat":"Compatibilitatea uitată","p-observe":"Diagnosticul prin ghicit"}};
